const express = require('express');
const session = require('express-session');
const helmet = require('helmet');
const BetterSqlite3Store = require('better-sqlite3-session-store')(session);
const config = require('./config');
const { getDb } = require('./db');
const healthRoutes = require('./routes/health');
const openaiRoutes = require('./routes/openai');
const adminRoutes = require('./routes/admin');
const studentPortalRoutes = require('./routes/studentPortal');
const { createGoogleAuthRouter } = require('./routes/googleAuth');
const { notFound, errorHandler } = require('./middleware/errorHandler');
const { jsonBody } = require('./middleware/bodyParsers');
const { rejectCrossSiteRequests } = require('./middleware/sameOrigin');
const { apiError } = require('./utils/errors');
const { getSetting } = require('./services/settingsService');

if (!BetterSqlite3Store.prototype.__ietiIntervalPatched) {
  BetterSqlite3Store.prototype.startInterval = function startInterval() {
    this._clearExpiredInterval = setInterval(
      this.clearExpiredSessions.bind(this),
      this.expired.intervalMs
    );
    this._clearExpiredInterval.unref?.();
  };
  BetterSqlite3Store.prototype.close = function close() {
    if (this._clearExpiredInterval) clearInterval(this._clearExpiredInterval);
    this._clearExpiredInterval = null;
  };
  BetterSqlite3Store.prototype.__ietiIntervalPatched = true;
}

function createApp({ googleOAuthService, googleIdentityResolver } = {}) {
  const app = express();
  const sessionStore = new BetterSqlite3Store({ client: getDb(), expired: { clear: true, intervalMs: 900000 } });

  app.disable('x-powered-by');
  app.set('trust proxy', config.trustProxy);
  app.locals.sessionStore = sessionStore;
  // Pages still use inline scripts and handlers, so scripts allow 'unsafe-inline'. The other
  // directives still block loading code from other origins, sending data to them, framing
  // and plugins.
  app.use(helmet({
    // Same-origin referrers keep form posts' Origin header meaningful without leaking
    // invite URLs to other sites.
    referrerPolicy: { policy: 'same-origin' },
    contentSecurityPolicy: {
      useDefaults: false,
      directives: {
        defaultSrc: ["'self'"],
        baseUri: ["'self'"],
        objectSrc: ["'none'"],
        frameAncestors: ["'none'"],
        formAction: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
        scriptSrcAttr: ["'unsafe-inline'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'blob:'],
        fontSrc: ["'self'", 'data:'],
        connectSrc: ["'self'"]
      }
    }
  }));
  app.use(jsonBody);
  app.use(express.urlencoded({ extended: false, limit: '128kb' }));
  app.use(rejectCrossSiteRequests);
  app.use(session({
    name: 'ieti_proxy_sid',
    secret: config.sessionSecret,
    store: sessionStore,
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: config.sessionCookieSecure,
      maxAge: 8 * 60 * 60 * 1000
    }
  }));

  app.use((req, res, next) => {
    if (req.path.startsWith('/admin') || req.path === '/health' || req.path === '/' || req.path === '/login' || req.path.startsWith('/portal') || req.path.startsWith('/downloads') || req.path.startsWith('/auth/google')) return next();
    if (getSetting('maintenance_mode', 'false') === 'true') {
      return next(apiError(503, 'maintenance_mode', 'Server is in maintenance mode.'));
    }
    next();
  });

  app.use(healthRoutes);
  app.use(createGoogleAuthRouter({ oauthService: googleOAuthService, identityResolver: googleIdentityResolver }));
  app.use(studentPortalRoutes);
  app.use(adminRoutes);
  app.use(openaiRoutes);
  app.use(notFound);
  app.use(errorHandler);

  return app;
}

module.exports = { createApp };

const path = require('path');

const rootDir = path.resolve(__dirname, '..');
require('dotenv').config({ path: path.join(rootDir, 'settings.env'), quiet: true });

function numberEnv(name, fallback) {
  const value = process.env[name];
  if (value === undefined || value === '') return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function boolEnv(name, fallback) {
  const value = process.env[name];
  if (value === undefined || value === '') return fallback;
  return ['1', 'true', 'yes', 'on'].includes(String(value).toLowerCase());
}

function googleCallbackUrl(publicBaseUrl) {
  const value = String(publicBaseUrl || '').trim().replace(/\/+$/, '');
  if (!value) return '';
  try {
    const url = new URL(value);
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) return '';
    return `${url.toString().replace(/\/$/, '')}/auth/google/callback`;
  } catch {
    return '';
  }
}

// Express "trust proxy" value. The default only trusts forwarding headers sent from
// loopback and private-network addresses, so internet clients cannot spoof their IP.
function trustProxyEnv(name, fallback) {
  const value = String(process.env[name] ?? '').trim();
  if (!value) return fallback;
  if (['true', 'false'].includes(value.toLowerCase())) return value.toLowerCase() === 'true';
  if (/^\d+$/.test(value)) return Number(value);
  return value;
}

const DEFAULT_ADMIN_PASSWORD = 'replace_with_a_secure_admin_password';
const DEFAULT_SESSION_SECRET = 'development_session_secret_change_me';
const PLACEHOLDER_SECRETS = new Set([
  DEFAULT_ADMIN_PASSWORD,
  DEFAULT_SESSION_SECRET,
  'replace_with_a_strong_password',
  'replace_with_a_long_random_session_secret'
]);

const publicBaseUrl = process.env.PUBLIC_BASE_URL || '';
const adminPassword = process.env.ADMIN_PASSWORD || DEFAULT_ADMIN_PASSWORD;
const adminPasswordHash = process.env.ADMIN_PASSWORD_HASH || '';
const sessionSecret = process.env.SESSION_SECRET || DEFAULT_SESSION_SECRET;

// An internet-facing server (production mode, or a public HTTPS URL) refuses to start
// with the publicly known defaults or example placeholders.
if (process.env.NODE_ENV === 'production' || /^https:\/\//i.test(publicBaseUrl.trim())) {
  const problems = [];
  if (!adminPasswordHash && (PLACEHOLDER_SECRETS.has(adminPassword) || adminPassword.length < 12)) {
    problems.push('ADMIN_PASSWORD must be set to a non-default value of at least 12 characters (or set ADMIN_PASSWORD_HASH)');
  }
  if (PLACEHOLDER_SECRETS.has(sessionSecret) || sessionSecret.length < 32) {
    problems.push('SESSION_SECRET must be set to a random value of at least 32 characters');
  }
  if (problems.length) throw new Error(`Refusing to start an internet-facing server: ${problems.join('; ')}.`);
}
const googleOAuthEnabled = boolEnv('GOOGLE_OAUTH_ENABLED', false);
const googleOAuthAllowedDomains = process.env.GOOGLE_OAUTH_ALLOWED_DOMAINS || '';

if (googleOAuthEnabled) {
  const missing = [
    ['GOOGLE_OAUTH_CLIENT_ID', process.env.GOOGLE_OAUTH_CLIENT_ID],
    ['GOOGLE_OAUTH_CLIENT_SECRET', process.env.GOOGLE_OAUTH_CLIENT_SECRET],
    ['PUBLIC_BASE_URL', publicBaseUrl],
    ['GOOGLE_OAUTH_ALLOWED_DOMAINS', googleOAuthAllowedDomains]
  ].filter(([, value]) => !String(value || '').trim()).map(([name]) => name);
  if (missing.length) throw new Error(`Google OAuth is enabled but these settings are missing: ${missing.join(', ')}`);
  if (!googleCallbackUrl(publicBaseUrl)) throw new Error('PUBLIC_BASE_URL must be a valid HTTP or HTTPS URL when Google OAuth is enabled.');
}

module.exports = {
  rootDir,
  port: numberEnv('PORT', 3000),
  databasePath: path.resolve(rootDir, process.env.DATABASE_PATH || './data/agents_proxy.sqlite'),
  defaultProviderApiKey: process.env.DEFAULT_PROVIDER_API_KEY || '',
  defaultProviderBaseUrl: process.env.DEFAULT_PROVIDER_BASE_URL || 'https://api.deepseek.com',
