const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');
const config = require('../config');

let db;

const DEFAULT_GROUP_LIMITS = {
  dailyCallLimit: 1000000000,
  dailyTokenLimit: 1000000000,
  hourlyCallLimit: 100000000,
  hourlyTokenLimit: 100000000
};

function getDb() {
  if (db) return db;
  fs.mkdirSync(path.dirname(config.databasePath), { recursive: true, mode: 0o700 });
  db = new Database(config.databasePath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  initSchema(db);
  migrateSchema(db);
  seedSettings(db);
  restrictDatabaseFilePermissions(config.databasePath);
  return db;
}

// The database holds provider API keys and password hashes, so only the server's own
// account may read it. SQLite creates the WAL and shared-memory files next to it.
function restrictDatabaseFilePermissions(databasePath) {
  for (const file of [databasePath, `${databasePath}-wal`, `${databasePath}-shm`]) {
    try {
      fs.chmodSync(file, 0o600);
    } catch (error) {
      if (error.code !== 'ENOENT') console.warn(`Could not restrict permissions on ${file}: ${error.message}`);
    }
  }
}

function initSchema(database) {
  database.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      email TEXT NOT NULL UNIQUE,
      api_key_hash TEXT,
      enabled INTEGER NOT NULL DEFAULT 1,
      role TEXT NOT NULL DEFAULT 'student',
      registration_status TEXT NOT NULL DEFAULT 'approved' CHECK (registration_status IN ('pending', 'approved', 'rejected')),
      auth_version INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      last_used_at TEXT
    );

    CREATE TABLE IF NOT EXISTS user_api_keys (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      name TEXT NOT NULL COLLATE NOCASE,
      api_key_hash TEXT NOT NULL,
      api_key_lookup_hash TEXT NOT NULL UNIQUE,
      api_key_prefix TEXT,
      api_key_suffix TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      last_used_at TEXT,
      UNIQUE(user_id, name)
    );

    CREATE TABLE IF NOT EXISTS user_identities (
      provider TEXT NOT NULL,
      subject TEXT NOT NULL,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      email_at_link TEXT NOT NULL,
      last_email TEXT NOT NULL,
      hosted_domain TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      last_login_at TEXT,
      PRIMARY KEY (provider, subject),
      UNIQUE (user_id, provider)
    );

    CREATE TABLE IF NOT EXISTS oauth_identity_conflicts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      replacement_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      provider TEXT NOT NULL,
      proposed_subject TEXT NOT NULL,
      verified_email TEXT NOT NULL,
      display_name TEXT NOT NULL,
      hosted_domain TEXT,
      status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'resolved', 'rejected')),
      resolution TEXT CHECK (resolution IS NULL OR resolution IN ('preserve', 'reset', 'reject')),
      requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      expires_at TEXT NOT NULL,
      resolved_at TEXT,
      resolved_by TEXT,
      UNIQUE (provider, proposed_subject)
    );

    CREATE TABLE IF NOT EXISTS auth_audit_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      event TEXT NOT NULL,
      user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      email TEXT,
      actor TEXT NOT NULL,
      details TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS conversations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      external_conversation_id TEXT,
      title TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      conversation_id INTEGER REFERENCES conversations(id) ON DELETE SET NULL,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      role TEXT NOT NULL,
      content TEXT NOT NULL,
      token_count INTEGER,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS usage_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      model TEXT NOT NULL,
      provider_slug TEXT,
      input_tokens INTEGER NOT NULL DEFAULT 0,
      output_tokens INTEGER NOT NULL DEFAULT 0,
      total_tokens INTEGER NOT NULL DEFAULT 0,
      was_streaming INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL,
      error_message TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS providers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      slug TEXT NOT NULL UNIQUE,
      name TEXT NOT NULL,
      kind TEXT NOT NULL DEFAULT 'openai-compatible',
      base_url TEXT NOT NULL,
      api_key TEXT NOT NULL DEFAULT '',
      enabled INTEGER NOT NULL DEFAULT 1,
      keep_warm_interval_minutes INTEGER NOT NULL DEFAULT 0 CHECK (keep_warm_interval_minutes IN (0, 1, 5)),
      priority INTEGER NOT NULL DEFAULT 100,
      max_concurrent_requests INTEGER,
      timeout_ms INTEGER,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS provider_models (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      provider_id INTEGER NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
      public_model TEXT NOT NULL,
      upstream_model TEXT NOT NULL,
      name TEXT NOT NULL,
      enabled INTEGER NOT NULL DEFAULT 1,
      context_limit INTEGER,
      output_limit INTEGER,
      supports_text_input INTEGER NOT NULL DEFAULT 1,
      supports_image_input INTEGER NOT NULL DEFAULT 1,
      supports_tools INTEGER NOT NULL DEFAULT 1,
      supports_reasoning INTEGER NOT NULL DEFAULT 1,
      reasoning_efforts TEXT,
      default_reasoning_effort TEXT,
      reasoning_history_field TEXT,
      supports_chat_template_kwargs INTEGER NOT NULL DEFAULT 0,
      supports_parallel_tools INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(provider_id, public_model)
    );

    CREATE TABLE IF NOT EXISTS groups (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      provider_id INTEGER REFERENCES providers(id) ON DELETE SET NULL,
      daily_call_limit INTEGER,
      daily_token_limit INTEGER,
      hourly_call_limit INTEGER,
      hourly_token_limit INTEGER,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS user_groups (
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
      PRIMARY KEY (user_id, group_id)
    );

    CREATE TABLE IF NOT EXISTS group_providers (
      group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
      provider_id INTEGER NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
      enabled INTEGER NOT NULL DEFAULT 1,
      priority INTEGER NOT NULL DEFAULT 100,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY (group_id, provider_id)
    );

    CREATE INDEX IF NOT EXISTS idx_usage_logs_user_created ON usage_logs(user_id, created_at);
    CREATE INDEX IF NOT EXISTS idx_usage_logs_status_created ON usage_logs(status, created_at);
    CREATE INDEX IF NOT EXISTS idx_usage_logs_created_id ON usage_logs(created_at, id);
    CREATE INDEX IF NOT EXISTS idx_user_groups_group ON user_groups(group_id);
    CREATE INDEX IF NOT EXISTS idx_group_providers_provider ON group_providers(provider_id);
    CREATE INDEX IF NOT EXISTS idx_user_identities_user ON user_identities(user_id);
    CREATE INDEX IF NOT EXISTS idx_oauth_conflicts_status ON oauth_identity_conflicts(status, requested_at);
    CREATE INDEX IF NOT EXISTS idx_auth_audit_user_created ON auth_audit_logs(user_id, created_at);
  `);
}

function migrateSchema(database) {
  const columns = database.prepare('PRAGMA table_info(users)').all().map((column) => column.name);
  const addColumn = (name, definition) => {
    if (!columns.includes(name)) database.exec(`ALTER TABLE users ADD COLUMN ${name} ${definition}`);
  };

  addColumn('password_hash', 'TEXT');
  addColumn('password_changed_at', 'TEXT');
  addColumn('invite_token_hash', 'TEXT');
  addColumn('invite_token_nonce', 'TEXT');
  addColumn('invite_expires_at', 'TEXT');
  addColumn('invite_used_at', 'TEXT');
  addColumn('failed_login_count', 'INTEGER NOT NULL DEFAULT 0');
  addColumn('locked_until', 'TEXT');
  addColumn('api_key_prefix', 'TEXT');
  addColumn('api_key_suffix', 'TEXT');
  addColumn('api_key_lookup_hash', 'TEXT');
  addColumn('registration_status', "TEXT NOT NULL DEFAULT 'approved' CHECK (registration_status IN ('pending', 'approved', 'rejected'))");
  addColumn('auth_version', 'INTEGER NOT NULL DEFAULT 0');
  addColumn('disabled_at', 'TEXT');
  // Existing disabled accounts have no reliable disable date. Start their
  // deletion waiting period now rather than inferring it from unrelated edits.
  database.exec(`
    UPDATE users SET disabled_at = CURRENT_TIMESTAMP
    WHERE enabled = 0 AND disabled_at IS NULL;

    CREATE TRIGGER IF NOT EXISTS users_track_disabled_insert
    AFTER INSERT ON users
    WHEN NEW.enabled = 0 AND NEW.disabled_at IS NULL
    BEGIN
      UPDATE users SET disabled_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
    END;

    CREATE TRIGGER IF NOT EXISTS users_track_disabled_update
    AFTER UPDATE OF enabled ON users
    WHEN OLD.enabled != NEW.enabled
    BEGIN
      UPDATE users
      SET disabled_at = CASE WHEN NEW.enabled = 0 THEN CURRENT_TIMESTAMP ELSE NULL END
      WHERE id = NEW.id;
    END;
  `);
  for (const name of ['daily_token_limit', 'monthly_token_limit', 'monthly_cost_limit_eur', 'allowed_models']) {
    if (columns.includes(name)) database.exec(`ALTER TABLE users DROP COLUMN ${name}`);
  }

  const usageColumns = database.prepare('PRAGMA table_info(usage_logs)').all().map((column) => column.name);
  if (!usageColumns.includes('provider_slug')) {
    database.exec('ALTER TABLE usage_logs ADD COLUMN provider_slug TEXT');
  }
  if (usageColumns.includes('estimated_cost_eur')) {
    database.exec('ALTER TABLE usage_logs DROP COLUMN estimated_cost_eur');
  }

  const providerColumns = database.prepare('PRAGMA table_info(providers)').all().map((column) => column.name);
  if (!providerColumns.includes('keep_warm_interval_minutes')) {
    database.exec('ALTER TABLE providers ADD COLUMN keep_warm_interval_minutes INTEGER NOT NULL DEFAULT 0 CHECK (keep_warm_interval_minutes IN (0, 1, 5))');
