      AND base_url LIKE 'https://api.deepseek.com%'
      AND EXISTS (SELECT 1 FROM providers WHERE slug = 'deepseek' AND enabled = 1)
  `).run();
}

function seedSettings(database) {
  const insert = database.prepare(`
    INSERT OR IGNORE INTO settings (key, value, updated_at)
    VALUES (?, ?, CURRENT_TIMESTAMP)
  `);

  const defaults = {
    public_base_url: config.publicBaseUrl,
    default_daily_token_limit: String(config.defaultDailyTokenLimit),
    default_model_context_limit: String(config.defaultModelContextLimit),
    default_model_output_limit: String(config.defaultModelOutputLimit),
    maintenance_mode: 'false',
    max_tokens_per_request: String(config.maxTokensPerRequest),
    max_requests_per_minute: String(config.maxRequestsPerMinute),
    max_images_per_request: String(config.maxImagesPerRequest),
    max_image_bytes: String(config.maxImageBytes),
    max_total_image_bytes: String(config.maxTotalImageBytes),
    allow_video_input: String(config.allowVideoInput)
  };

  for (const [key, value] of Object.entries(defaults)) {
    insert.run(key, value);
  }

  // An environment value is deployment configuration and remains authoritative
  // even when the database was created before PUBLIC_BASE_URL was added.
  if (config.publicBaseUrl) {
    database.prepare(`
      INSERT INTO settings (key, value, updated_at)
      VALUES ('public_base_url', ?, CURRENT_TIMESTAMP)
      ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = CURRENT_TIMESTAMP
    `).run(config.publicBaseUrl);
  }

  seedDefaultProvider(database);
  seedDefaultGroup(database);
}

function seedDefaultProvider(database) {
  const providerCount = database.prepare('SELECT COUNT(*) AS count FROM providers').get().count;
  if (providerCount > 0) return;
  const setting = (key, fallback) => database.prepare('SELECT value FROM settings WHERE key = ?').get(key)?.value ?? fallback;
  const contextLimit = Number(setting('default_model_context_limit', config.defaultModelContextLimit));

  const provider = database.prepare(`
    INSERT INTO providers (slug, name, kind, base_url, api_key, enabled, priority, max_concurrent_requests, timeout_ms)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    config.defaultProviderSlug,
    config.defaultProviderName,
    'openai-compatible',
    config.defaultProviderBaseUrl,
    config.defaultProviderApiKey,
    config.defaultProviderApiKey ? 1 : 0,
    200,
    null,
    config.requestTimeoutMs
  );

  database.prepare(`
    INSERT INTO provider_models
      (provider_id, public_model, upstream_model, name, enabled, context_limit, output_limit)
    VALUES (?, ?, ?, ?, 1, ?, ?)
  `).run(
    provider.lastInsertRowid,
    config.publicModelName,
    config.defaultUpstreamModel,
    config.defaultProviderName,
    contextLimit,
    8192
  );
}

function seedDefaultGroup(database) {
  const groupCount = database.prepare('SELECT COUNT(*) AS count FROM groups').get().count;
  const providerId = database.prepare('SELECT id FROM providers ORDER BY priority DESC, name ASC LIMIT 1').get()?.id ?? null;
  let groupId = database.prepare('SELECT id FROM groups ORDER BY name ASC LIMIT 1').get()?.id;

  if (groupCount === 0) {
    const group = database.prepare(`
      INSERT INTO groups
        (name, provider_id, daily_call_limit, daily_token_limit, hourly_call_limit, hourly_token_limit)
      VALUES (?, ?, ?, ?, ?, ?)
    `).run(
      'Default Users',
      providerId,
      DEFAULT_GROUP_LIMITS.dailyCallLimit,
      DEFAULT_GROUP_LIMITS.dailyTokenLimit,
      DEFAULT_GROUP_LIMITS.hourlyCallLimit,
      DEFAULT_GROUP_LIMITS.hourlyTokenLimit
    );
    groupId = group.lastInsertRowid;
  }

  if (groupId) {
    database.prepare(`
      INSERT OR IGNORE INTO user_groups (user_id, group_id)
      SELECT users.id, ?
      FROM users
      WHERE users.registration_status = 'approved'
        AND NOT EXISTS (
        SELECT 1 FROM user_groups WHERE user_groups.user_id = users.id
      )
    `).run(groupId);
  }
}

function closeDb() {
  if (db) {
    db.close();
    db = undefined;
  }
}

module.exports = { getDb, closeDb, initSchema, migrateSchema, seedSettings };

const { getDb } = require('../db');
const { keyPrefixSuffix, lookupHashApiKey, verifyApiKey } = require('../services/keyService');
const { apiError } = require('../utils/errors');

function extractBearer(req) {
  const header = req.get('authorization') || '';
  const match = header.match(/^Bearer\s+(.+)$/i);
  return match ? match[1].trim() : null;
}

async function authStudent(req, res, next) {
  try {
    const apiKey = extractBearer(req);
    if (!apiKey) throw apiError(401, 'missing_api_key', 'Missing Authorization bearer token.');

    const db = getDb();
    // Keys carry 256 random bits, so a SHA-256 lookup match proves possession on its own.
    // bcrypt costs hundreds of milliseconds, so it is reserved for legacy rows that
    // predate the lookup hash; they are migrated on first use.
    const lookupHash = lookupHashApiKey(apiKey);
    let user = db.prepare(`
      SELECT users.*, user_api_keys.id AS authenticated_api_key_id
      FROM user_api_keys
      JOIN users ON users.id = user_api_keys.user_id
      WHERE user_api_keys.api_key_lookup_hash = ?
    `).get(lookupHash);

    if (!user) {
      user = db.prepare('SELECT * FROM users WHERE api_key_hash IS NOT NULL AND api_key_lookup_hash = ?').get(lookupHash);
    }

    if (!user) {
      const { prefix, suffix } = keyPrefixSuffix(apiKey);
      const legacyUsers = db.prepare(`
        SELECT *
        FROM users
        WHERE api_key_hash IS NOT NULL
          AND api_key_lookup_hash IS NULL
          AND api_key_prefix = ?
          AND api_key_suffix = ?
      `).all(prefix, suffix);
      user = null;
      for (const candidate of legacyUsers) {
        if (await verifyApiKey(apiKey, candidate.api_key_hash)) {
          user = candidate;
          break;
        }
      }
    }

    if (user && !user.authenticated_api_key_id) {
      db.prepare('UPDATE users SET api_key_lookup_hash = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(lookupHash, user.id);
      db.prepare(`
        INSERT OR IGNORE INTO user_api_keys
          (user_id, name, api_key_hash, api_key_lookup_hash, api_key_prefix, api_key_suffix, created_at, last_used_at)
        VALUES (?, 'Default', ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
      `).run(user.id, user.api_key_hash, lookupHash, user.api_key_prefix, user.api_key_suffix, user.created_at);
      user = { ...user, api_key_lookup_hash: lookupHash };
    }

    if (!user) throw apiError(401, 'invalid_api_key', 'Invalid or revoked API key.');
    if (!user.enabled) throw apiError(403, 'user_disabled', 'This user is disabled.');
    if (user.registration_status !== 'approved') {
      throw apiError(403, user.registration_status === 'pending' ? 'account_pending' : 'account_rejected',
        user.registration_status === 'pending' ? 'This account is awaiting administrator approval.' : 'This account is not approved.');
    }

    if (user.authenticated_api_key_id) {
      db.prepare('UPDATE user_api_keys SET last_used_at = CURRENT_TIMESTAMP WHERE id = ?').run(user.authenticated_api_key_id);
    }
    db.prepare('UPDATE users SET last_used_at = CURRENT_TIMESTAMP WHERE id = ?').run(user.id);

    req.student = user;
    next();
  } catch (error) {
    next(error);
  }
}

module.exports = { authStudent };

const { apiError } = require('../utils/errors');
const { getSetting } = require('../services/settingsService');

const buckets = new Map();
const oauthBuckets = new Map();
const loginFailures = new Map();

const LOGIN_WINDOW_MS = 15 * 60_000;
const MAX_LOGIN_FAILURES_PER_ACCOUNT_AND_ADDRESS = 10;
const MAX_LOGIN_FAILURES_PER_ADDRESS = 100;

// Buckets are keyed by user id or client address. Expired ones are swept so a stream of
// distinct addresses cannot grow these maps without bound.
const sweepTimer = setInterval(() => {
  const now = Date.now();
  for (const map of [buckets, oauthBuckets, loginFailures]) {
    for (const [key, bucket] of map) {
      if (now > bucket.resetAt) map.delete(key);
    }
  }
}, 60_000);
sweepTimer.unref?.();

function hit(map, key, windowMs) {
  const now = Date.now();
  let bucket = map.get(key);
  if (!bucket || now > bucket.resetAt) {
    bucket = { count: 0, resetAt: now + windowMs };
    map.set(key, bucket);
  }
  bucket.count += 1;
  return bucket;
}

function countIn(map, key) {
  const bucket = map.get(key);
  return bucket && Date.now() <= bucket.resetAt ? bucket.count : 0;
}

function studentRateLimit(req, res, next) {
  try {
    const user = req.student;
    if (!user) return next();
    const max = Number(getSetting('max_requests_per_minute', 1000));
    const bucket = hit(buckets, String(user.id), 60_000);

    res.set('X-RateLimit-Limit', String(max));
    res.set('X-RateLimit-Remaining', String(Math.max(0, max - bucket.count)));
    res.set('X-RateLimit-Reset', String(Math.ceil(bucket.resetAt / 1000)));

    if (bucket.count > max) {
      throw apiError(429, 'rate_limit_exceeded', 'Rate limit exceeded.');
    }

    next();
  } catch (error) {
    next(error);
  }
}

function oauthRateLimit(req, res, next) {
  try {
    const bucket = hit(oauthBuckets, `oauth:${req.ip}`, 10 * 60_000);
    if (bucket.count > 20) throw apiError(429, 'oauth_rate_limit_exceeded', 'Too many sign-in attempts. Try again later.');
    next();
  } catch (error) {
    next(error);
  }
}

function loginKeys(ip, login) {
  return { address: `ip:${ip}`, account: `account:${ip}:${String(login || '').trim().toLowerCase()}` };
}

// Covers admin and student password logins alike.
function isLoginAllowed(ip, login) {
  const { address, account } = loginKeys(ip, login);
  return countIn(loginFailures, address) < MAX_LOGIN_FAILURES_PER_ADDRESS &&
    countIn(loginFailures, account) < MAX_LOGIN_FAILURES_PER_ACCOUNT_AND_ADDRESS;
}

function recordLoginFailure(ip, login) {
  const { address, account } = loginKeys(ip, login);
  hit(loginFailures, address, LOGIN_WINDOW_MS);
  hit(loginFailures, account, LOGIN_WINDOW_MS);
}

function clearLoginFailures(ip, login) {
  loginFailures.delete(loginKeys(ip, login).account);
}

module.exports = { clearLoginFailures, isLoginAllowed, oauthRateLimit, recordLoginFailure, studentRateLimit };

