const { getDb } = require('../db');

function providerPoolForGroup(groupId) {
  if (!groupId) return [];
  return getDb().prepare(`
    SELECT providers.id, providers.slug, providers.name, group_providers.priority
    FROM group_providers
    JOIN providers ON providers.id = group_providers.provider_id
    WHERE group_providers.group_id = ?
      AND group_providers.enabled = 1
    ORDER BY group_providers.priority DESC, providers.priority DESC, providers.name ASC
  `).all(groupId);
}

function attachProviderPool(group) {
  if (!group) return null;
  const providers = providerPoolForGroup(group.id);
  const fallbackProvider = group.provider_slug
    ? [{ id: group.provider_id, slug: group.provider_slug, name: group.provider_name }]
    : [];
  const pool = providers.length ? providers : fallbackProvider;
  return {
    ...group,
    providers: pool,
    provider_slugs: pool.map((provider) => provider.slug).filter(Boolean),
    provider_names: pool.map((provider) => provider.name || provider.slug).filter(Boolean).join(', '),
    provider_slug: pool[0]?.slug || group.provider_slug || null,
    provider_name: pool[0]?.name || group.provider_name || null
  };
}

function getAllGroups() {
  return getDb().prepare(`
    SELECT groups.*, providers.slug AS provider_slug, providers.name AS provider_name
    FROM groups
    LEFT JOIN providers ON providers.id = groups.provider_id
    ORDER BY groups.name ASC
  `).all().map(attachProviderPool);
}

function getUserGroups(userId) {
  return getDb().prepare(`
    SELECT groups.*
    FROM groups
    JOIN user_groups ON user_groups.group_id = groups.id
    WHERE user_groups.user_id = ?
    ORDER BY groups.name ASC
  `).all(userId).map(attachProviderPool);
}

function getUserGroup(userId) {
  const group = getDb().prepare(`
    SELECT groups.*, providers.slug AS provider_slug, providers.name AS provider_name
    FROM groups
    JOIN user_groups ON user_groups.group_id = groups.id
    LEFT JOIN providers ON providers.id = groups.provider_id
    WHERE user_groups.user_id = ?
    ORDER BY groups.name ASC
    LIMIT 1
  `).get(userId);
  return attachProviderPool(group);
}

function setUserGroups(userId, groupIds) {
  const db = getDb();
  const id = groupIds.map(Number).find(Number.isFinite);
  const tx = db.transaction(() => {
    db.prepare('DELETE FROM user_groups WHERE user_id = ?').run(userId);
    if (id) db.prepare('INSERT OR REPLACE INTO user_groups (user_id, group_id) VALUES (?, ?)').run(userId, id);
  });
  tx();
}

function setGroupProviders(groupId, providerIds) {
  const ids = [...new Set(providerIds.map(Number).filter((id) => Number.isInteger(id) && id > 0))];
  const db = getDb();
  const validIds = ids.length
    ? db.prepare(`SELECT id FROM providers WHERE id IN (${ids.map(() => '?').join(',')})`).all(...ids).map((row) => row.id)
    : [];
  const primaryProviderId = validIds[0] || null;

  const tx = db.transaction(() => {
    db.prepare('UPDATE groups SET provider_id = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(primaryProviderId, groupId);
    db.prepare('DELETE FROM group_providers WHERE group_id = ?').run(groupId);
    const insert = db.prepare(`
      INSERT INTO group_providers (group_id, provider_id, enabled, priority, updated_at)
      VALUES (?, ?, 1, ?, CURRENT_TIMESTAMP)
    `);
    validIds.forEach((providerId, index) => insert.run(groupId, providerId, 100 - index));
  });
  tx();
}

module.exports = {
  attachProviderPool,
  getAllGroups,
  getUserGroup,
  getUserGroups,
  providerPoolForGroup,
  setGroupProviders,
  setUserGroups
};

const config = require('../config');
const { normalizeChatReasoning, normalizeReasoningEvent } = require('../utils/reasoningHistory');
const { callChatCompletions } = require('./providerService');
const { checkQuota } = require('./quotaService');
const { recordUsage } = require('./usageService');
const { estimateChatTokens, estimateTokensFromText } = require('../utils/tokens');
const { validateRequestPayload } = require('../utils/payloadValidation');
const { apiError } = require('../utils/errors');
const { affinityContextFromRequest } = require('./conversationAffinityService');
const { providerAvailability } = require('./providerAvailabilityService');

function failedAttemptUsage(error) {
  const usage = error.upstreamUsage;
  const inputTokens = Math.max(0, Number(usage?.prompt_tokens ?? usage?.input_tokens) || 0);
  const outputTokens = Math.max(0, Number(usage?.completion_tokens ?? usage?.output_tokens) || 0);
  return { inputTokens, outputTokens, totalTokens: Math.max(0, Number(usage?.total_tokens) || inputTokens + outputTokens) };
}

function recordFailedAttempt({ userId, model, wasStreaming }, error) {
  recordUsage({ userId, model, wasStreaming, providerSlug: error.providerSlug, ...failedAttemptUsage(error), status: 'upstream_retry', errorMessage: error.message });
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function responseIsClosed(res) {
  return res.destroyed || res.writableEnded;
}

function createStreamInactivityTimer(controller) {
  let timer;
  const reset = () => {
    clearTimeout(timer);
    timer = setTimeout(() => controller.abort(), config.streamInactivityTimeoutMs);
  };
  const clear = () => clearTimeout(timer);
  reset();
  return { clear, reset };
}

async function handleChatCompletion(req, res, next) {
  const user = req.student;
  const payload = req.body || {};
  const model = payload.model || '';
  const wasStreaming = Boolean(payload.stream);
  let estimatedInputTokens = 0;
  let timeout;
  let releaseProvider;
  let releaseQuota;
  let providerSlug = null;
  let providerRequestStarted = false;
  let completeProvider;
  let failProvider;
  let clientDisconnected = false;
  const controller = new AbortController();
  const disconnect = () => {
    if (res.writableEnded) return;
    clientDisconnected = true;
    controller.abort();
  };
  req.once('aborted', disconnect);
  res.once('close', disconnect);

  try {
    estimatedInputTokens = estimateChatTokens(payload);
    if (req.aborted || responseIsClosed(res)) {
      clientDisconnected = true;
      throw new DOMException('Client disconnected.', 'AbortError');
    }
    if (!Array.isArray(payload.messages)) {
      throw apiError(400, 'invalid_request', 'messages must be an array.');
    }
    if (!model) {
      throw apiError(503, 'no_models_available', 'No enabled provider models are available.');
    }
    if (wasStreaming && !config.enableStreaming) {
      throw apiError(400, 'streaming_disabled', 'Streaming is disabled on this server.');
    }
    validateRequestPayload(payload);
    const { group, maxTokens, release: quotaRelease } = checkQuota({
      user,
      model,
      estimatedInputTokens,
      requestedMaxTokens: Number(payload.max_tokens || 0)
    });
    releaseQuota = quotaRelease;
    timeout = setTimeout(() => controller.abort(), config.requestTimeoutMs);

    // Always request streamed usage so accounting uses the provider's real token counts.
    const streamOptions = isPlainObject(payload.stream_options) ? payload.stream_options : {};
    const upstreamPayload = {
      ...payload,
      model,
      ...(maxTokens ? { max_tokens: maxTokens } : {}),
      ...(wasStreaming ? { stream_options: { ...streamOptions, include_usage: true } } : {})
    };
    providerRequestStarted = true;
    const { upstream, provider, release, complete, fail } = await callChatCompletions(upstreamPayload, {
      signal: controller.signal,
      providerSlugs: group.provider_slugs,
      conversation: affinityContextFromRequest(req),
      onAttemptFailure: (error) => recordFailedAttempt({ userId: user.id, model, wasStreaming }, error)
    });
    releaseProvider = release;
    completeProvider = complete;
    failProvider = fail;
    providerSlug = provider.slug;

    if (wasStreaming) {
      clearTimeout(timeout);
      timeout = undefined;
      await streamResponse({
        upstream,
        res,
        userId: user.id,
        model,
        providerSlug,
        estimatedInputTokens,
        controller,
        completeProvider,
        failProvider,
        forwardUsageChunks: streamOptions.include_usage === true,
        isClientDisconnected: () => clientDisconnected
      });
      return;
    }

    const body = normalizeChatReasoning(await upstream.json());
    if (clientDisconnected || responseIsClosed(res)) {
      throw new DOMException('Client disconnected.', 'AbortError');
    }
    const usage = normalizeUsage(body.usage, estimatedInputTokens, body);
    completeProvider(body.choices?.[0]?.message);
    recordUsage({
      userId: user.id,
      model,
      providerSlug,
      inputTokens: usage.inputTokens,
      outputTokens: usage.outputTokens,
      totalTokens: usage.totalTokens,
      wasStreaming: false,
      status: 'success'
    });
    res.json(body);
  } catch (error) {
    const cancelled = clientDisconnected || responseIsClosed(res);
    const timedOut = !cancelled && error.name === 'AbortError';
    if (!cancelled) {
      if (failProvider) failProvider();
      else if (timedOut && error.providerSlug) providerAvailability.failed(error.providerSlug);
    }
    const upstreamUsage = error.upstreamAttempt && !(cancelled && providerRequestStarted && !error.upstreamUsage) ? failedAttemptUsage(error) : null;
    const inputTokens = upstreamUsage?.inputTokens ?? (cancelled && !providerRequestStarted ? 0 : estimatedInputTokens);
    providerSlug = error.providerSlug || providerSlug;
    recordUsage({
      userId: user?.id,
      model,
      providerSlug,
      inputTokens,
      outputTokens: upstreamUsage?.outputTokens || 0,
      totalTokens: upstreamUsage?.totalTokens ?? inputTokens,
      wasStreaming,
      status: cancelled ? 'cancelled' : timedOut ? 'timeout' : upstreamUsage?.totalTokens > 0 ? 'upstream_error' : 'error',
      errorMessage: cancelled ? 'Client disconnected.' : timedOut ? 'Provider request timed out.' : error.message
    });
    if (cancelled || res.headersSent) {
      if (!responseIsClosed(res)) res.end();
      return;
    }
    next(timedOut ? apiError(504, 'provider_timeout', 'Provider request timed out.') : error);
  } finally {
    if (timeout) clearTimeout(timeout);
    req.removeListener('aborted', disconnect);
    res.removeListener('close', disconnect);
    releaseProvider?.();
    releaseQuota?.();
  }
}

async function streamResponse({ upstream, res, userId, model, providerSlug, estimatedInputTokens, controller, isClientDisconnected, completeProvider, failProvider, forwardUsageChunks = true }) {
  let reader;
  let inactivityTimer;
  let outputText = '';
  let reasoningText = '';
  let usageFromStream = null;
  let streamFinished = false;
  const toolCalls = new Map();
  const outputEstimate = () => estimateTokensFromText(outputText) + estimateTokensFromText(reasoningText) +
    estimateTokensFromText([...toolCalls.values()].map((entry) => entry.function.arguments).join(''));
  const inspectEvent = (event) => {
    const data = event.split(/\r?\n/)
      .filter((line) => line.startsWith('data:'))
      .map((line) => line.slice(5).trimStart()).join('\n');
    if (!data) return;
    if (data === '[DONE]') { streamFinished = true; return; }
    let parsed;
    try {
      parsed = JSON.parse(data);
    } catch {
      // Preserve malformed upstream SSE fragments without treating them as usage.
      return;
    }
    if (parsed.usage) usageFromStream = parsed.usage;
    if (parsed.error) throw new Error(parsed.error.message || 'The upstream stream failed.');
    if (parsed.choices?.some((choice) => choice.finish_reason)) streamFinished = true;
    const delta = parsed.choices?.[0]?.delta || {};
    if (typeof delta.content === 'string') outputText += delta.content;
    const reasoning = delta.reasoning_content ?? delta.reasoning;
    if (typeof reasoning === 'string') reasoningText += reasoning;
    for (const tool of delta.tool_calls || []) {
      const index = Number(tool.index || 0);
      const entry = toolCalls.get(index) || { id: '', type: 'function', function: { name: '', arguments: '' } };
      if (tool.id) entry.id = tool.id;
      if (tool.type) entry.type = tool.type;
      entry.function.name += tool.function?.name || '';
      entry.function.arguments += tool.function?.arguments || '';
      toolCalls.set(index, entry);
    }
    return Boolean(parsed.usage) && Array.isArray(parsed.choices) && parsed.choices.length === 0;
  };
  const writeEvent = (event, separator = '') => {
    if (isClientDisconnected() || responseIsClosed(res)) {
      throw new DOMException('Client disconnected.', 'AbortError');
    }
    const usageOnlyChunk = inspectEvent(event);
    // Clients that did not ask for usage do not expect the final chunk with no choices.
    if (usageOnlyChunk && !forwardUsageChunks) return;
    res.write(normalizeReasoningEvent(event) + separator);
  };

  try {
    if (isClientDisconnected() || responseIsClosed(res)) {
      throw new DOMException('Client disconnected.', 'AbortError');
    }
    res.status(upstream.status);
    res.set({
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no'
    });
    res.flushHeaders?.();
    const decoder = new TextDecoder();
    reader = upstream.body.getReader();
    inactivityTimer = createStreamInactivityTimer(controller);
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      inactivityTimer.reset();
      buffer += decoder.decode(value, { stream: true });
      const events = buffer.split(/(\r?\n\r?\n)/);
      buffer = events.pop() || '';
      for (let index = 0; index < events.length; index += 2) {
        writeEvent(events[index], events[index + 1]);
      }
    }
    buffer += decoder.decode();
    if (buffer) writeEvent(buffer);
    if (isClientDisconnected() || responseIsClosed(res)) {
      throw new DOMException('Client disconnected.', 'AbortError');
    }
    if (!streamFinished) throw new Error('The upstream stream ended before completion.');
    const usage = normalizeUsage(usageFromStream, estimatedInputTokens, null, outputEstimate());
    completeProvider({ role: 'assistant', content: outputText, ...(toolCalls.size ? { tool_calls: [...toolCalls.values()] } : {}) });
    recordUsage({
      userId,
      model,
      providerSlug,
      inputTokens: usage.inputTokens,
      outputTokens: usage.outputTokens,
      totalTokens: usage.totalTokens,
      wasStreaming: true,
      status: 'success'
    });
    res.end();
  } catch (error) {
    controller.abort();
    const cancelled = isClientDisconnected() || responseIsClosed(res);
    if (!cancelled) failProvider?.();
    const consumed = Boolean(usageFromStream || outputEstimate() > 0);
    const usage = normalizeUsage(usageFromStream, cancelled || consumed ? estimatedInputTokens : 0, null, outputEstimate());
    recordUsage({
      userId,
      model,
      providerSlug,
      inputTokens: usage.inputTokens,
      outputTokens: usage.outputTokens,
      totalTokens: usage.totalTokens,
      wasStreaming: true,
      status: cancelled ? 'cancelled' : consumed ? 'upstream_error' : 'error',
      errorMessage: cancelled ? 'Client disconnected.' : error.message
    });
    if (!cancelled) {
      try {
        res.write(`event: error\ndata: ${JSON.stringify({ error: { message: 'Streaming failed.', code: 'stream_error' } })}\n\n`);
        res.end();
      } catch {
        // A disconnected client cannot receive the stream error; usage is already recorded.
      }
    }
  } finally {
    inactivityTimer?.clear();
    reader?.releaseLock();
  }
}

function normalizeUsage(usage, estimatedInputTokens, body, estimatedOutputTokens = null) {
  const promptTokens = usage?.prompt_tokens ?? usage?.input_tokens ?? estimatedInputTokens;
  const completionTokens = usage?.completion_tokens ?? usage?.output_tokens ?? estimatedOutputTokens ?? estimateTokensFromText(JSON.stringify(body?.choices || ''));
  return {
    inputTokens: Number(promptTokens) || 0,
    outputTokens: Number(completionTokens) || 0,
    totalTokens: Number(usage?.total_tokens) || ((Number(promptTokens) || 0) + (Number(completionTokens) || 0))
  };
}

module.exports = { failedAttemptUsage, handleChatCompletion, recordFailedAttempt };

const crypto = require('node:crypto');
const { apiError } = require('../utils/errors');

const AFFINITY_TTL_MS = 30 * 60 * 1000;
const MAX_AFFINITY_ENTRIES = 10000;

function opaqueConversationId(value) {
  if (value === undefined || value === null) return null;
  if (typeof value !== 'string' || !value.length || value.length > 256 || /\s|[\x00-\x1f\x7f]/.test(value)) {
    throw apiError(400, 'invalid_conversation_id', 'conversation_id must be an opaque string of 1–256 characters without whitespace.');
  }
  return value;
}

function affinityContextFromRequest(req, payload = req.body || {}) {
  return {
    userId: req.student?.id,
    conversationId: opaqueConversationId(payload.conversation_id ?? payload.metadata?.conversation_id ??
      (typeof payload.conversation === 'string' ? payload.conversation : payload.conversation?.id) ??
      req.get?.('x-conversation-id'))
  };
}

function stableJson(value) {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().filter((key) => value[key] !== undefined)
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function canonicalMessage(message) {
  let content = message.content ?? '';
  if (Array.isArray(content) && content.every((part) => ['text', 'input_text', 'output_text'].includes(part?.type))) {
    content = content.map((part) => part.text || '').join('');
  }
  return {
    role: message.role === 'developer' ? 'system' : message.role,
    content,
    ...(message.name ? { name: message.name } : {}),
    ...(message.tool_call_id ? { tool_call_id: message.tool_call_id } : {}),
    ...(message.tool_calls?.length ? { tool_calls: message.tool_calls } : {})
  };
}

function digest(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

// Only hashes, provider identifiers and timestamps survive a request. Completed
// assistant boundaries distinguish continuations from shared initial templates.
function createAffinityStore({ now = Date.now, ttlMs = AFFINITY_TTL_MS, maxEntries = MAX_AFFINITY_ENTRIES } = {}) {
  const entries = new Map();
  function prune() {
    for (const [key, entry] of entries) {
      if (now() - entry.at < ttlMs) break;
      entries.delete(key);
    }
  }
  function remember(key, providerSlug) {
    prune();
    entries.delete(key);
    entries.set(key, { providerSlug, at: now() });
    while (entries.size > maxEntries) entries.delete(entries.keys().next().value);
  }
  function lookup(key) {
    prune();
    const entry = entries.get(key);
    if (!entry) return null;
    remember(key, entry.providerSlug);
    return entry.providerSlug;
  }
  function request({ userId, model, conversationId = null, messages = [] }) {
    const historyHash = crypto.createHash('sha256');
    const prefixes = [];
    let hasUser = false;
    let hasAssistant = false;
    for (const message of messages) {
      const canonical = canonicalMessage(message);
      historyHash.update(stableJson(canonical)).update('\n');
      if (canonical.role === 'user') hasUser = true;
      if (canonical.role === 'assistant' && hasUser && (canonical.content || canonical.tool_calls?.length)) hasAssistant = true;
      if (hasAssistant && canonical.role !== 'system') {
        prefixes.push(historyHash.copy().digest('hex'));
        if (prefixes.length > 64) prefixes.shift();
      }
    }
    let scope;
    function setPool(slugs) {
      scope = userId === undefined || userId === null ? null : digest(stableJson([userId, model, [...slugs].sort()]));
      if (!scope) return null;
      if (conversationId) return lookup(`${scope}:id:${digest(conversationId)}`);
      for (let index = prefixes.length - 1; index >= 0; index--) {
        const providerSlug = lookup(`${scope}:prefix:${prefixes[index]}`);
        if (providerSlug) return providerSlug;
      }
      return null;
    }
    function complete(providerSlug, assistantMessage) {
      if (!scope) return;
      if (conversationId) {
        remember(`${scope}:id:${digest(conversationId)}`, providerSlug);
        return;
      }
      if (hasAssistant) remember(`${scope}:prefix:${historyHash.copy().digest('hex')}`, providerSlug);
      if (hasUser && assistantMessage && (assistantMessage.content || assistantMessage.tool_calls?.length)) {
        const completedHash = historyHash.copy().update(stableJson(canonicalMessage(assistantMessage))).update('\n').digest('hex');
        remember(`${scope}:prefix:${completedHash}`, providerSlug);
      }
    }
    return { setPool, complete };
  }
  return { request, size: () => { prune(); return entries.size; } };
}

const affinityStore = createAffinityStore();
module.exports = { AFFINITY_TTL_MS, MAX_AFFINITY_ENTRIES, affinityContextFromRequest, affinityStore, createAffinityStore, opaqueConversationId };

const crypto = require('node:crypto');
const { OAuth2Client } = require('google-auth-library');
const config = require('../config');

function parseAllowedDomains(value) {
  const domains = [...new Set(String(value || '')
    .split(',')
    .map((domain) => domain.trim().toLowerCase().replace(/^@/, ''))
    .filter(Boolean))];
  if (!domains.length) throw new Error('GOOGLE_OAUTH_ALLOWED_DOMAINS must contain at least one domain or *');
  if (domains.includes('*') && domains.length !== 1) throw new Error('GOOGLE_OAUTH_ALLOWED_DOMAINS=* cannot be combined with named domains.');
  for (const domain of domains) {
    if (domain === '*') continue;
    if (!/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(domain)) {
      throw new Error(`Invalid Google OAuth hosted domain: ${domain}`);
    }
  }
  return domains;
}

function safeEqual(left, right) {
  const leftBuffer = Buffer.from(String(left || ''));
  const rightBuffer = Buffer.from(String(right || ''));
  return leftBuffer.length === rightBuffer.length && crypto.timingSafeEqual(leftBuffer, rightBuffer);
}

function normalizeProfile(payload, expectedNonce, allowedDomains) {
  if (!payload || !safeEqual(payload.nonce, expectedNonce)) throw new Error('Google ID token nonce did not match the sign-in request.');
  if (!payload.sub) throw new Error('Google ID token is missing its subject.');
  if (!payload.email || payload.email_verified !== true) throw new Error('Google account email is missing or is not verified.');
  const email = String(payload.email).trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Google returned an invalid email address.');
  const hostedDomain = String(payload.hd || '').trim().toLowerCase();
  if (allowedDomains[0] !== '*' && (!hostedDomain || !allowedDomains.includes(hostedDomain))) {
    throw new Error('Google account is not in an allowed hosted domain.');
  }
  const fallbackName = email.split('@')[0];
  const displayName = String(payload.name || fallbackName).trim().slice(0, 160) || fallbackName;
  return {
    provider: 'google',
    subject: String(payload.sub),
    email,
    emailVerified: true,
    hostedDomain: hostedDomain || null,
    displayName
  };
}

function createGoogleOAuthService() {
  const allowedDomains = config.googleOAuthEnabled ? parseAllowedDomains(config.googleOAuthAllowedDomains) : [];
  let client;
  const getClient = () => {
    if (!config.googleOAuthEnabled) throw new Error('Google OAuth is disabled.');
    if (!client) {
      client = new OAuth2Client({
        clientId: config.googleOAuthClientId,
        clientSecret: config.googleOAuthClientSecret,
        redirectUri: config.googleOAuthCallbackUrl
      });
    }
    return client;
  };

  return {
    isEnabled() {
      return config.googleOAuthEnabled;
    },

    async createAuthorizationRequest({ state, nonce }) {
      const oauthClient = getClient();
      const { codeVerifier, codeChallenge } = await oauthClient.generateCodeVerifierAsync();
      const url = oauthClient.generateAuthUrl({
        access_type: 'online',
        scope: ['openid', 'email', 'profile'],
        prompt: 'select_account',
        state,
        nonce,
        code_challenge: codeChallenge,
        code_challenge_method: 'S256'
      });
      return { url, codeVerifier };
    },

    async exchangeAndVerify({ code, codeVerifier, nonce }) {
      const oauthClient = getClient();
      const { tokens } = await oauthClient.getToken({
        code,
        codeVerifier,
        redirect_uri: config.googleOAuthCallbackUrl
      });
      if (!tokens.id_token) throw new Error('Google did not return an ID token.');
      const ticket = await oauthClient.verifyIdToken({
        idToken: tokens.id_token,
        audience: config.googleOAuthClientId
      });
      return normalizeProfile(ticket.getPayload(), nonce, allowedDomains);
    }
  };
}

module.exports = {
  createGoogleOAuthService,
  normalizeProfile,
  parseAllowedDomains,
  safeEqual
};

const config = require('../config');
const { getDb } = require('../db');

const CONFLICT_LIFETIME_MS = 7 * 24 * 60 * 60 * 1000;

function auditAuthEvent(db, { event, userId = null, email = null, actor = 'system', details = null }) {
  db.prepare(`
    INSERT INTO auth_audit_logs (event, user_id, email, actor, details)
    VALUES (?, ?, ?, ?, ?)
  `).run(event, userId, email, actor, details ? JSON.stringify(details) : null);
}

function invalidateInvite(db, userId) {
  db.prepare(`
    UPDATE users
    SET invite_used_at = CASE WHEN invite_token_nonce IS NOT NULL OR invite_token_hash IS NOT NULL THEN CURRENT_TIMESTAMP ELSE invite_used_at END,
        invite_token_hash = NULL, invite_token_nonce = NULL, invite_expires_at = NULL,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = ?
  `).run(userId);
}

function createOrRefreshConflict(db, user, currentIdentity, profile) {
  const now = new Date().toISOString();
  const expiresAt = new Date(Date.now() + CONFLICT_LIFETIME_MS).toISOString();
  const existing = db.prepare(`
    SELECT * FROM oauth_identity_conflicts
    WHERE provider = ? AND proposed_subject = ?
  `).get(profile.provider, profile.subject);
  if (existing && existing.status !== 'pending') return existing;
  if (existing) {
    db.prepare(`
      UPDATE oauth_identity_conflicts
      SET user_id = ?, verified_email = ?, display_name = ?, hosted_domain = ?,
          requested_at = ?, expires_at = ?
      WHERE id = ?
    `).run(user.id, profile.email, profile.displayName, profile.hostedDomain, now, expiresAt, existing.id);
    return db.prepare('SELECT * FROM oauth_identity_conflicts WHERE id = ?').get(existing.id);
  }
  const result = db.prepare(`
    INSERT INTO oauth_identity_conflicts
      (user_id, provider, proposed_subject, verified_email, display_name, hosted_domain, requested_at, expires_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `).run(user.id, profile.provider, profile.subject, profile.email, profile.displayName, profile.hostedDomain, now, expiresAt);
  auditAuthEvent(db, {
    event: 'oauth_identity_conflict_created',
    userId: user.id,
    email: profile.email,
    actor: 'google_oauth',
    details: { provider: profile.provider, currentSubject: currentIdentity.subject, proposedSubject: profile.subject }
  });
  return db.prepare('SELECT * FROM oauth_identity_conflicts WHERE id = ?').get(result.lastInsertRowid);
}

function resolveGoogleSignIn(profile) {
  const db = getDb();
  return db.transaction(() => {
    const linked = db.prepare(`
      SELECT users.*, user_identities.last_email AS identity_last_email
      FROM user_identities
      JOIN users ON users.id = user_identities.user_id
      WHERE user_identities.provider = ? AND user_identities.subject = ?
    `).get(profile.provider, profile.subject);
    if (linked) {
      db.prepare(`
        UPDATE user_identities
        SET last_email = ?, hosted_domain = ?, last_login_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
        WHERE provider = ? AND subject = ?
      `).run(profile.email, profile.hostedDomain, profile.provider, profile.subject);
      if (!linked.enabled || linked.registration_status === 'rejected') {
        return { kind: 'denied' };
      }
      return { kind: 'login', user: linked };
    }

    const user = db.prepare('SELECT * FROM users WHERE lower(email) = lower(?)').get(profile.email);
    if (user) {
      if (!user.enabled || user.registration_status === 'rejected') return { kind: 'denied' };
      const currentIdentity = db.prepare(`
        SELECT * FROM user_identities WHERE user_id = ? AND provider = ?
      `).get(user.id, profile.provider);
      if (currentIdentity) {
        const conflict = createOrRefreshConflict(db, user, currentIdentity, profile);
        return { kind: conflict.status === 'pending' ? 'conflict' : 'denied', conflict };
      }
      db.prepare(`
        INSERT INTO user_identities
          (provider, subject, user_id, email_at_link, last_email, hosted_domain, last_login_at)
        VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
      `).run(profile.provider, profile.subject, user.id, profile.email, profile.email, profile.hostedDomain);
      invalidateInvite(db, user.id);
      auditAuthEvent(db, {
        event: 'oauth_identity_linked',
        userId: user.id,
        email: profile.email,
        actor: 'google_oauth',
        details: { provider: profile.provider, subject: profile.subject }
      });
      return { kind: 'login', user: db.prepare('SELECT * FROM users WHERE id = ?').get(user.id) };
    }

    if (!config.googleOAuthAutoRegister) return { kind: 'denied' };
    const created = db.prepare(`
      INSERT INTO users (name, email, enabled, role, registration_status)
      VALUES (?, ?, 1, 'student', 'pending')
    `).run(profile.displayName, profile.email);
    const userId = created.lastInsertRowid;
    db.prepare(`
      INSERT INTO user_identities
        (provider, subject, user_id, email_at_link, last_email, hosted_domain, last_login_at)
      VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
    `).run(profile.provider, profile.subject, userId, profile.email, profile.email, profile.hostedDomain);
    auditAuthEvent(db, {
      event: 'oauth_user_registered_pending',
      userId,
      email: profile.email,
      actor: 'google_oauth',
      details: { provider: profile.provider, subject: profile.subject, hostedDomain: profile.hostedDomain }
    });
    return { kind: 'login', user: db.prepare('SELECT * FROM users WHERE id = ?').get(userId) };
  })();
}

function listIdentityConflicts() {
  return getDb().prepare(`
    SELECT oauth_identity_conflicts.*, users.name AS user_name, users.email AS user_email,
           user_identities.subject AS current_subject
    FROM oauth_identity_conflicts
    LEFT JOIN users ON users.id = oauth_identity_conflicts.user_id
    LEFT JOIN user_identities
      ON user_identities.user_id = users.id AND user_identities.provider = oauth_identity_conflicts.provider
    ORDER BY CASE oauth_identity_conflicts.status WHEN 'pending' THEN 0 ELSE 1 END,
             oauth_identity_conflicts.requested_at DESC
  `).all();
}

function pendingConflict(db, conflictId) {
  const conflict = db.prepare('SELECT * FROM oauth_identity_conflicts WHERE id = ?').get(conflictId);
  if (!conflict || conflict.status !== 'pending') return null;
  if (new Date(conflict.expires_at).getTime() <= Date.now()) return null;
  return conflict;
}

function preserveIdentityConflict(conflictId, adminUsername) {
  const db = getDb();
  return db.transaction(() => {
    const conflict = pendingConflict(db, conflictId);
    if (!conflict?.user_id) return null;
    const user = db.prepare('SELECT * FROM users WHERE id = ?').get(conflict.user_id);
    if (!user) return null;
    const identity = db.prepare('SELECT * FROM user_identities WHERE user_id = ? AND provider = ?').get(user.id, conflict.provider);
    if (!identity) return null;
    const proposedOwner = db.prepare('SELECT user_id FROM user_identities WHERE provider = ? AND subject = ?').get(conflict.provider, conflict.proposed_subject);
    if (proposedOwner && Number(proposedOwner.user_id) !== Number(user.id)) return null;
    db.prepare(`
      UPDATE user_identities
      SET subject = ?, last_email = ?, hosted_domain = ?, updated_at = CURRENT_TIMESTAMP, last_login_at = NULL
      WHERE provider = ? AND subject = ?
    `).run(conflict.proposed_subject, conflict.verified_email, conflict.hosted_domain, conflict.provider, identity.subject);
    invalidateInvite(db, user.id);
    db.prepare('UPDATE users SET auth_version = auth_version + 1, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(user.id);
    db.prepare(`
      UPDATE oauth_identity_conflicts
      SET status = 'resolved', resolution = 'preserve', resolved_at = CURRENT_TIMESTAMP, resolved_by = ?
      WHERE id = ?
    `).run(adminUsername, conflict.id);
    auditAuthEvent(db, {
      event: 'oauth_identity_replaced_preserve',
      userId: user.id,
      email: user.email,
      actor: adminUsername,
      details: { previousSubject: identity.subject, replacementSubject: conflict.proposed_subject }
    });
    return { userId: user.id };
  })();
}

function resetIdentityConflict(conflictId, adminUsername) {
  const db = getDb();
  return db.transaction(() => {
    const conflict = pendingConflict(db, conflictId);
    if (!conflict?.user_id) return null;
    const oldUser = db.prepare('SELECT * FROM users WHERE id = ?').get(conflict.user_id);
    if (!oldUser) return null;
    const oldUserId = oldUser.id;
    db.prepare('DELETE FROM users WHERE id = ?').run(oldUserId);
    const created = db.prepare(`
      INSERT INTO users (name, email, enabled, role, registration_status)
      VALUES (?, ?, 1, 'student', 'pending')
    `).run(conflict.display_name, conflict.verified_email);
    const replacementUserId = created.lastInsertRowid;
    db.prepare(`
      INSERT INTO user_identities
        (provider, subject, user_id, email_at_link, last_email, hosted_domain)
      VALUES (?, ?, ?, ?, ?, ?)
    `).run(conflict.provider, conflict.proposed_subject, replacementUserId, conflict.verified_email, conflict.verified_email, conflict.hosted_domain);
    db.prepare(`
      UPDATE oauth_identity_conflicts
      SET replacement_user_id = ?, status = 'resolved', resolution = 'reset',
          resolved_at = CURRENT_TIMESTAMP, resolved_by = ?
      WHERE id = ?
    `).run(replacementUserId, adminUsername, conflict.id);
    auditAuthEvent(db, {
      event: 'oauth_identity_reset_new_user',
      userId: replacementUserId,
      email: conflict.verified_email,
      actor: adminUsername,
      details: { deletedUserId: oldUserId, replacementSubject: conflict.proposed_subject }
    });
    return { userId: replacementUserId };
  })();
}

function rejectIdentityConflict(conflictId, adminUsername) {
  const db = getDb();
  return db.transaction(() => {
    const conflict = pendingConflict(db, conflictId);
    if (!conflict) return null;
    db.prepare(`
      UPDATE oauth_identity_conflicts
      SET status = 'rejected', resolution = 'reject', resolved_at = CURRENT_TIMESTAMP, resolved_by = ?
      WHERE id = ?
    `).run(adminUsername, conflict.id);
    auditAuthEvent(db, {
      event: 'oauth_identity_conflict_rejected',
      userId: conflict.user_id,
      email: conflict.verified_email,
      actor: adminUsername,
      details: { proposedSubject: conflict.proposed_subject }
    });
    return { userId: conflict.user_id };
  })();
}

module.exports = {
  auditAuthEvent,
  invalidateInvite,
  listIdentityConflicts,
  preserveIdentityConflict,
  rejectIdentityConflict,
  resetIdentityConflict,
  resolveGoogleSignIn
};

const config = require('../config');
const { getDb } = require('../db');
const { chatCompletionsUrl, getInFlight, reserveProviderForTest } = require('./providerService');

const KEEP_WARM_INTERVAL_MS = 60000;
const KEEP_WARM_TIMEOUT_MS = 30000;

function createProviderKeepWarmService({ database = getDb, fetchImpl = fetch, logger = console, now = Date.now } = {}) {
  const active = new Map();
  const lastAttemptAt = new Map();
  let timer;
  let stopped = false;

  async function warm(provider, checkedAt) {
    // Existing traffic already keeps the provider warm. Leave its capacity for students.
    if (active.has(provider.id) || getInFlight(provider.slug) > 0) return;
    const previousAttempt = lastAttemptAt.get(provider.id);
    const intervalMs = provider.keep_warm_interval_minutes * KEEP_WARM_INTERVAL_MS;
    if (previousAttempt !== undefined && checkedAt - previousAttempt < intervalMs) return;
    const controller = new AbortController();
    active.set(provider.id, controller);
    let release;
    try {
      release = reserveProviderForTest(provider.slug);
      // Anchor the cadence so a delayed callback does not skip the following minute.
      lastAttemptAt.set(provider.id, previousAttempt === undefined ? checkedAt
        : previousAttempt + Math.floor((checkedAt - previousAttempt) / intervalMs) * intervalMs);
      const timeoutMs = Math.max(1, Math.min(
        Number(provider.timeout_ms || config.requestTimeoutMs), KEEP_WARM_TIMEOUT_MS
      ));
      const response = await fetchImpl(chatCompletionsUrl(provider.base_url), {
        method: 'POST',
        redirect: 'error',
        headers: {
          Authorization: `Bearer ${provider.api_key}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: provider.upstream_model,
          messages: [{ role: 'user', content: 'Reply OK.' }],
          max_tokens: Math.min(8, Number(provider.output_limit) || 8),
          stream: false
        }),
        signal: AbortSignal.any([controller.signal, AbortSignal.timeout(timeoutMs)])
      });
      // Keep the timeout and capacity reservation until the response body finishes.
      await response.text();
      if (!response.ok) logger.warn(`Keep warm failed for provider ${provider.id}: HTTP ${response.status}.`);
    } catch {
      // Never log upstream bodies, URLs, credentials or student content.
      if (!controller.signal.aborted) logger.warn(`Keep warm failed for provider ${provider.id}: request failed or timed out.`);
    } finally {
      release?.();
      active.delete(provider.id);
    }
  }

  async function runOnce() {
    if (stopped) return;
    const checkedAt = now();
    try {
      const providers = database().prepare(`
        SELECT providers.*, provider_models.upstream_model, provider_models.output_limit
        FROM providers
        JOIN provider_models ON provider_models.id = (
          SELECT id FROM provider_models
          WHERE provider_id = providers.id AND enabled = 1 AND supports_text_input = 1
          ORDER BY updated_at DESC, id DESC LIMIT 1
        )
        WHERE providers.enabled = 1 AND providers.keep_warm_interval_minutes IN (1, 5)
          AND TRIM(providers.base_url) != '' AND TRIM(providers.api_key) != ''
          AND TRIM(provider_models.upstream_model) != ''
      `).all();
      const eligibleIds = new Set(providers.map((provider) => provider.id));
      for (const id of lastAttemptAt.keys()) {
        if (!eligibleIds.has(id)) lastAttemptAt.delete(id);
      }
      await Promise.all(providers.map((provider) => warm(provider, checkedAt)));
    } catch {
      logger.warn('Keep warm could not read provider settings. It will retry on the next interval.');
    }
  }

  function start() {
    if (timer) return;
    stopped = false;
    void runOnce();
    timer = setInterval(() => { void runOnce(); }, KEEP_WARM_INTERVAL_MS);
    timer.unref?.();
  }

  function stop() {
    stopped = true;
    if (timer) clearInterval(timer);
    timer = undefined;
    lastAttemptAt.clear();
    for (const controller of active.values()) controller.abort();
  }

  return { start, stop, runOnce };
}

module.exports = { createProviderKeepWarmService, KEEP_WARM_INTERVAL_MS };

const { deflateSync } = require('node:zlib');
const { prepareAssistantHistory } = require('../utils/reasoningHistory');

// Catalog discovery runs in the route; retries belong to their original stage.
const AUTOCONFIGURE_TOTAL_STAGES = 6;

// A small synthetic red/blue image. No student content is sent during discovery.
function probeImage() {
  function chunk(type, data) {
    const content = Buffer.concat([Buffer.from(type), data]);
    let crc = 0xffffffff;
    for (const byte of content) {
      crc ^= byte;
      for (let i = 0; i < 8; i++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
    }
    const size = Buffer.alloc(4), checksum = Buffer.alloc(4);
    size.writeUInt32BE(data.length); checksum.writeUInt32BE((crc ^ 0xffffffff) >>> 0);
    return Buffer.concat([size, content, checksum]);
  }
  const width = 128, height = 128;
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width); header.writeUInt32BE(height, 4); header[8] = 8; header[9] = 2;
  const pixels = Buffer.alloc(height * (width * 3 + 1));
  for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
    pixels[y * (width * 3 + 1) + 1 + x * 3 + (x < width / 2 ? 0 : 2)] = 255;
  }
  return 'data:image/png;base64,' + Buffer.concat([
    Buffer.from('89504e470d0a1a0a', 'hex'), chunk('IHDR', header),
    chunk('IDAT', deflateSync(pixels)), chunk('IEND', Buffer.alloc(0))
  ]).toString('base64');
}

function missingThinking(result) {
  return [400, 422].includes(result.httpStatus) && /assistant message is missing a thinking field/i.test(result.message);
}

function explicitlyUnsupported(result, feature) {
  if (![400, 422].includes(result.httpStatus)) return false;
  const text = result.message.toLowerCase();
  const names = feature === 'image' ? /image|vision|multi.?modal/ : /tool|function.call/;
  return names.test(text) && /not support|unsupported|does not have|not a multimodal|only support.*text|requires.*(?:parser|enable.auto)|must.*(?:parser|enable.auto)|cannot.*(?:image|tool)/.test(text);
}

async function probeProviderModel({ baseUrl, apiKey = '', model, timeoutMs = 60000, budgetMs = 180000, fetchImpl = fetch, signal, onProgress }) {
  const clean = baseUrl.replace(/\/+$/, '');
  const url = `${clean}${clean.endsWith('/v1') ? '' : '/v1'}/chat/completions`;
  const deadline = Date.now() + budgetMs;
  const settings = {}, results = [];
  let stage = 2;
  const reportProgress = (activeTest, completedStages = stage - 1) => onProgress?.({
    activeTest, stage, totalStages: AUTOCONFIGURE_TOTAL_STAGES, completedStages,
    results: results.map((item) => ({ ...item }))
  });
  let testControls = {};
  const redact = (text) => {
    let value = String(text || '').replace(/Bearer\s+[^\s"']+/gi, 'Bearer [redacted]');
    if (apiKey) value = value.split(apiKey).join('[redacted]');
    return value.slice(0, 1500);
  };
  async function call(name, messages, extra = {}) {
    signal?.throwIfAborted();
    reportProgress(name);
    const start = Date.now();
    const result = { name, status: 'inconclusive', httpStatus: null, message: '', durationMs: 0 };
    results.push(result);
    if (deadline <= start) {
      result.message = 'Test budget exhausted; existing configuration is unchanged.';
      return result;
    }
    try {
      const response = await fetchImpl(url, {
        method: 'POST', redirect: 'error',
        headers: { 'Content-Type': 'application/json', ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}) },
        signal: AbortSignal.any([AbortSignal.timeout(Math.max(1, Math.min(timeoutMs, deadline - start))), ...(signal ? [signal] : [])]),
        body: JSON.stringify({ model, messages, max_tokens: 256, temperature: 0, stream: false, ...testControls, ...extra })
      });
      result.httpStatus = response.status;
      let body;
      try {
        if (extra.stream && response.ok) {
          const raw = await response.text();
          if (response.headers.get('content-type')?.includes('text/event-stream')) {
            let content = '', reasoning = '', finishReason = null, done = false;
            for (const event of raw.split(/\r?\n\r?\n/)) {
              const data = event.split(/\r?\n/).filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trimStart()).join('\n');
              if (!data) continue;
              if (data === '[DONE]') { done = true; continue; }
              const chunk = JSON.parse(data);
              if (chunk.error) { body = chunk; break; }
              const choice = chunk.choices?.[0];
              content += choice?.delta?.content || '';
              reasoning += choice?.delta?.reasoning_content ?? choice?.delta?.reasoning ?? '';
              finishReason = choice?.finish_reason || finishReason;
            }
            if (!body && done && finishReason) body = { choices: [{
              message: { role: 'assistant', content, reasoning_content: reasoning }, finish_reason: finishReason
            }] };
          }
        } else body = await response.json();
      } catch (error) {
        if (/timeout|abort/i.test(error.name)) throw error;
        // Invalid JSON/SSE is inconclusive.
      }
      if (!response.ok || body?.error) {
        const error = body?.error?.message || body?.message || body?.detail;
        result.hint = response.status === 401 || response.status === 403 ? 'Check the provider API key and its permissions.'
          : response.status === 429 ? 'Check the provider quota or concurrency limit and try again later.'
          : response.status === 404 ? 'Check the Base URL, chat endpoint and selected model.'
          : response.status >= 500 ? 'Check whether the inference server is ready, and inspect its logs.'
          : 'Review the rejected parameter or message format before changing capability settings.';
        result.message = redact(typeof error === 'string' ? error : error ? JSON.stringify(error) : response.statusText || 'Invalid upstream response.');
      } else if (body?.choices?.[0]?.message?.role === 'assistant') {
        // Keep response content private to the test; diagnostics only include outcomes.
        Object.defineProperty(result, 'assistant', { value: body.choices[0].message });
        Object.defineProperty(result, 'finished', { value: ['stop', 'tool_calls', 'function_call'].includes(body.choices[0].finish_reason) });
        result.message = result.finished ? 'The server returned an assistant message.'
          : body.choices[0].finish_reason === 'length' ? 'The test reached its output token limit; behavior may be inconclusive.'
          : 'The server did not report a completed response; behavior is inconclusive.';
        const reasoning = result.assistant.reasoning_content ?? result.assistant.reasoning;
        if (typeof reasoning === 'string' && reasoning.trim()) settings.supports_reasoning = 1;
      } else {
        result.message = extra.stream ? 'The streaming request did not return valid, completed SSE. OpenCode uses streaming; check the upstream protocol and logs.' : 'The response did not contain a valid assistant message.';
      }
    } catch (error) {
      result.message = /timeout|abort/i.test(error.name) ? 'The test timed out; this does not prove the capability is unsupported.' : redact(error.message);
    }
    result.durationMs = Date.now() - start;
    return result;
  }
  const success = (result) => result.assistant && result.finished && typeof result.assistant.content === 'string' && result.assistant.content.trim();
  function supported(result, message) { result.status = 'supported'; result.message = message; }
  const greeting = [{ role: 'user', content: 'Reply with exactly OK.' }];
  let text = await call('Text completion', greeting);
  if (text.assistant && !text.finished && settings.supports_reasoning) {
    const shorter = await call('Text completion with low reasoning effort', greeting, { reasoning_effort: 'low' });
    if (success(shorter)) {
      text = shorter;
      testControls = { reasoning_effort: 'low' };
      results.push({ name: 'Test parameters', status: 'inconclusive', httpStatus: null,
        message: 'Remaining tests use reasoning_effort=low to fit the test budget. Acceptance alone does not establish the full set of supported reasoning controls.' });
    }
  }
  if (success(text)) {
    settings.supports_text_input = 1;
    supported(text, 'A text completion succeeded.');
  }
  if (!text.assistant) {
    results.push({ name: 'Remaining tests', status: 'inconclusive', httpStatus: null,
      message: 'Skipped because the basic request failed. Check the Base URL, credentials, model availability and the error above.' });
    signal?.throwIfAborted();
    reportProgress(null, stage);
    return { settings, results };
  }

  const history = [...greeting, { role: 'assistant', content: 'OK' }, { role: 'user', content: 'Reply with exactly OK again.' }];
  stage = 3;
  const historyResult = await call('Assistant history without reasoning', history);
  if (success(historyResult)) {
    supported(historyResult, 'Ordinary assistant history is accepted; no missing-field workaround is required.');
    settings.reasoning_history_field = null;
  } else if (missingThinking(historyResult)) {
    historyResult.status = 'unsupported';
    const repaired = await call('Assistant history with reasoning_content', prepareAssistantHistory(history, 'reasoning_content'));
    if (success(repaired)) {
      supported(repaired, 'Verified: reasoning_content is accepted, including an empty value for history that has no reasoning. Existing reasoning must still be preserved.');
      settings.reasoning_history_field = 'reasoning_content';
    }
  }

  const tools = [{ type: 'function', function: { name: 'lookup_probe', description: 'Look up a synthetic test code.',
    parameters: { type: 'object', properties: { code: { type: 'string', enum: ['A', 'B'] } }, required: ['code'], additionalProperties: false } } }];
  const toolMessages = [{ role: 'user', content: 'Call lookup_probe twice, once with code A and once with code B. Do not guess the results. After receiving the results, reply with their values.' }];
  stage = 4;
  let toolResult = await call('Tool calling', toolMessages, { tools, tool_choice: 'auto', parallel_tool_calls: true });
  if ([400, 422].includes(toolResult.httpStatus) && /parallel_tool_calls/i.test(toolResult.message) && /not support|unsupported|not allowed|extra inputs/i.test(toolResult.message)) {
    settings.supports_parallel_tools = 0;
    toolResult.status = 'unsupported';
    toolResult = await call('Tool calling without parallel_tool_calls', toolMessages, { tools, tool_choice: 'auto' });
  }
  const calls = toolResult.assistant?.tool_calls;
  const validCalls = Array.isArray(calls) && calls.length > 0 && calls.length <= 2 && new Set(calls.map((item) => item.id)).size === calls.length && calls.every((item) => {
    try { return item.type === 'function' && typeof item.id === 'string' && item.id && item.function?.name === 'lookup_probe' && ['A', 'B'].includes(JSON.parse(item.function.arguments).code); }
    catch { return false; }
  });
  if (validCalls) {
    supported(toolResult, `The server produced ${calls.length} valid tool call(s). Testing the return of tool results next.`);
    let messages = [...toolMessages, toolResult.assistant, ...calls.map((item) => ({
      role: 'tool', tool_call_id: item.id, content: JSON.parse(item.function.arguments).code === 'A' ? 'violet' : 'amber'
    }))];
    messages = prepareAssistantHistory(messages, settings.reasoning_history_field);
    const roundTrip = await call('Tool result round trip', messages, { tools });
    const expected = calls.map((item) => JSON.parse(item.function.arguments).code === 'A' ? 'violet' : 'amber');
    if (success(roundTrip) && expected.every((value) => roundTrip.assistant.content.toLowerCase().includes(value))) {
      settings.supports_tools = 1;
      supported(roundTrip, 'The server accepted assistant/tool history and used the synthetic tool results. No real tools were executed.');
      if (settings.supports_parallel_tools !== 0 && new Set(calls.map((item) => JSON.parse(item.function.arguments).code)).size === 2) settings.supports_parallel_tools = 1;
    } else {
      toolResult.status = 'inconclusive';
      toolResult.message = 'Tool calls were produced, but the complete tool round trip was not verified. Review the next result.';
    }
  } else if (explicitlyUnsupported(toolResult, 'tools')) {
    settings.supports_tools = 0; settings.supports_parallel_tools = 0;
    toolResult.status = 'unsupported';
  } else if (toolResult.assistant) toolResult.message = 'No valid tool call was produced. Acceptance of the tools parameter alone does not verify tool support.';

  stage = 5;
  const image = await call('Image input', [{ role: 'user', content: [
    { type: 'text', text: 'Name the color of the left half and then the right half of this image. Reply with only the two color names, in that order.' },
    { type: 'image_url', image_url: { url: probeImage() } }
  ] }]);
  if (success(image) && /^\W*red\W+(?:and\W+)?blue\W*$/i.test(image.assistant.content.trim())) {
    settings.supports_image_input = 1;
    supported(image, 'The model correctly identified the two colors in the synthetic image.');
  } else if (explicitlyUnsupported(image, 'image')) {
    settings.supports_image_input = 0; image.status = 'unsupported';
  } else if (image.assistant) image.message = 'The model did not correctly describe the test image. Image support is inconclusive.';
  stage = 6;
  const streaming = await call('Streaming assistant history', prepareAssistantHistory(history, settings.reasoning_history_field), { stream: true, max_tokens: 128 });
  if (success(streaming)) supported(streaming, 'The server returned valid SSE and completed a streamed assistant-history request, as used by OpenCode.');
  else streaming.hint = 'OpenCode uses streaming. Review this result before relying on the model, even if non-streaming tests passed.';
  results.push({ name: 'Reasoning output', status: settings.supports_reasoning ? 'supported' : 'inconclusive', httpStatus: null,
    message: settings.supports_reasoning ? 'Nonempty reasoning was returned in reasoning or reasoning_content.' : 'No reasoning output was observed. This does not prove reasoning is unsupported.' });
  results.push({ name: 'Limits and reasoning controls', status: 'inconclusive', httpStatus: null,
    message: 'Tests do not infer maximum context/output limits or selectable reasoning efforts. Use published values or verify these settings manually. One successful sample does not guarantee every future request.' });
  signal?.throwIfAborted();
  reportProgress(null, stage);
  return { settings, results };
}

module.exports = { probeProviderModel, AUTOCONFIGURE_TOTAL_STAGES };

const config = require('../config');
const { prepareAssistantHistory } = require('../utils/reasoningHistory');
const { getDb } = require('../db');
const { apiError } = require('../utils/errors');
const { officialModelSettings } = require('../utils/providerMetadata');
const { affinityStore } = require('./conversationAffinityService');
const { providerAvailability } = require('./providerAvailabilityService');
const {
  CHAT_TEMPLATE_KWARG_NAMES,
  CHAT_TEMPLATE_KWARG_SET,
  REASONING_EFFORTS,
  normalizeReasoningEffort,
  parseReasoningEfforts
} = require('../utils/reasoning');

const COMPATIBLE_FIELDS = [
  'model',
  'messages',
  'temperature',
  'top_p',
  'max_tokens',
  'stream',
  'stream_options',
  'tools',
  'tool_choice',
  'parallel_tool_calls',
  'presence_penalty',
  'frequency_penalty',
  'reasoning_content',
  'reasoning_effort',
  'chat_template_kwargs',
  'response_format',
  'stop'
];

const inFlightByProvider = new Map();

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function validateReasoningControls(payload = {}) {
  const hasReasoningEffort = payload.reasoning_effort !== undefined && payload.reasoning_effort !== null;
  const reasoningEffort = hasReasoningEffort ? normalizeReasoningEffort(payload.reasoning_effort) : null;
  if (hasReasoningEffort && !reasoningEffort) {
    throw apiError(
      400,
      'invalid_reasoning_effort',
      `reasoning_effort must be one of: ${REASONING_EFFORTS.join(', ')}.`
    );
  }

  const hasChatTemplateKwargs = payload.chat_template_kwargs !== undefined && payload.chat_template_kwargs !== null;
  let chatTemplateKwargs = null;
  if (hasChatTemplateKwargs) {
    if (!isPlainObject(payload.chat_template_kwargs)) {
      throw apiError(400, 'invalid_chat_template_kwargs', 'chat_template_kwargs must be an object.');
    }
    const unknown = Object.keys(payload.chat_template_kwargs)
      .filter((name) => !CHAT_TEMPLATE_KWARG_SET.has(name));
    if (unknown.length) {
      throw apiError(
        400,
        'invalid_chat_template_kwargs',
        `Unsupported chat_template_kwargs: ${unknown.join(', ')}. Allowed fields: ${CHAT_TEMPLATE_KWARG_NAMES.join(', ')}.`
      );
    }
    chatTemplateKwargs = {};
    for (const name of ['enable_thinking', 'preserve_thinking']) {
      if (payload.chat_template_kwargs[name] === undefined) continue;
      if (typeof payload.chat_template_kwargs[name] !== 'boolean') {
        throw apiError(400, 'invalid_chat_template_kwargs', `${name} must be a boolean.`);
      }
      chatTemplateKwargs[name] = payload.chat_template_kwargs[name];
    }
    if (payload.chat_template_kwargs.reasoning_effort !== undefined) {
      const nestedEffort = normalizeReasoningEffort(payload.chat_template_kwargs.reasoning_effort);
      if (!nestedEffort) {
        throw apiError(
          400,
          'invalid_reasoning_effort',
          `chat_template_kwargs.reasoning_effort must be one of: ${REASONING_EFFORTS.join(', ')}.`
        );
      }
      if (reasoningEffort && nestedEffort !== reasoningEffort) {
        throw apiError(400, 'conflicting_reasoning_effort', 'reasoning_effort and chat_template_kwargs.reasoning_effort must match.');
      }
      chatTemplateKwargs.reasoning_effort = nestedEffort;
    }
  }

  const effectiveEffort = reasoningEffort || chatTemplateKwargs?.reasoning_effort || null;
  if (effectiveEffort && effectiveEffort !== 'none' && chatTemplateKwargs?.enable_thinking === false) {
    throw apiError(400, 'conflicting_reasoning_controls', 'enable_thinking=false cannot be combined with an active reasoning_effort.');
  }
  if (effectiveEffort === 'none' && chatTemplateKwargs?.enable_thinking === true) {
    throw apiError(400, 'conflicting_reasoning_controls', 'reasoning_effort=none cannot be combined with enable_thinking=true.');
  }

  return {
    reasoningEffort: effectiveEffort,
    chatTemplateKwargs,
    hasChatTemplateKwargs,
    reasoningRequested: Boolean(effectiveEffort || chatTemplateKwargs?.enable_thinking === true)
  };
}

function buildPayload(payload, upstreamModel, provider = {}) {
  const reasoning = validateReasoningControls(payload);
  const next = {};
  for (const field of COMPATIBLE_FIELDS) {
    if (payload[field] === undefined || payload[field] === null) continue;
    if (field === 'chat_template_kwargs') {
      next[field] = reasoning.chatTemplateKwargs;
    } else if (field === 'reasoning_effort') {
      next[field] = normalizeReasoningEffort(payload[field]);
    } else {
      next[field] = payload[field];
    }
  }
  next.messages = prepareAssistantHistory(next.messages, provider.reasoning_history_field);
  next.model = upstreamModel;
  const outputLimit = Number(provider.output_limit);
  if (Number.isFinite(outputLimit) && outputLimit > 0 && Number(next.max_tokens) > outputLimit) next.max_tokens = outputLimit;
  return next;
}

function chatCompletionsUrl(baseUrl) {
  const clean = String(baseUrl || '').replace(/\/+$/, '');
  return clean.endsWith('/v1') ? `${clean}/chat/completions` : `${clean}/v1/chat/completions`;
}

function modelsUrl(baseUrl) {
  const clean = String(baseUrl || '').replace(/\/+$/, '');
  return clean.endsWith('/v1') ? `${clean}/models` : `${clean}/v1/models`;
}

function providerRootUrl(baseUrl) {
  const clean = String(baseUrl || '').replace(/\/+$/, '');
  return clean.endsWith('/v1') ? clean.slice(0, -3) : clean;
}

function getProviderBySlug(slug) {
  return getDb().prepare('SELECT * FROM providers WHERE slug = ?').get(slug);
}

function listProviders() {
  return getDb().prepare('SELECT * FROM providers ORDER BY name ASC').all().map((provider) => ({
    ...provider,
    in_flight: getInFlight(provider.slug)
  }));
}

function getEnabledModelEntries() {
  const rows = getDb().prepare(`
    SELECT
      providers.slug,
      providers.name AS provider_name,
      provider_models.public_model,
      provider_models.name AS model_name,
      provider_models.context_limit,
      provider_models.output_limit,
      provider_models.supports_text_input,
      provider_models.supports_image_input,
      provider_models.supports_tools,
      provider_models.supports_reasoning,
      provider_models.reasoning_efforts,
      provider_models.default_reasoning_effort,
      provider_models.reasoning_history_field,
      provider_models.supports_chat_template_kwargs,
      provider_models.supports_parallel_tools,
      providers.priority
    FROM providers
    JOIN provider_models ON providers.id = provider_models.provider_id
    WHERE providers.enabled = 1 AND provider_models.enabled = 1
    ORDER BY providers.priority DESC, providers.name ASC, provider_models.id ASC
  `).all();
  return rows.map((row) => ({
      id: row.slug,
      publicModel: row.public_model,
      name: row.provider_name || row.slug,
      limit: {
        context: Number(row.context_limit || config.defaultModelContextLimit),
        output: Number(row.output_limit || config.defaultModelOutputLimit)
      },
      capabilities: {
        text: Boolean(row.supports_text_input),
        image: Boolean(row.supports_image_input),
        tools: Boolean(row.supports_tools),
        reasoning: Boolean(row.supports_reasoning),
        reasoningEfforts: parseReasoningEfforts(row.reasoning_efforts) || [],
        reasoningEffortsKnown: row.reasoning_efforts !== null,
        defaultReasoningEffort: normalizeReasoningEffort(row.default_reasoning_effort),
        chatTemplateKwargs: Boolean(row.supports_chat_template_kwargs),
        parallelTools: Boolean(row.supports_parallel_tools)
      }
  }));
}

function getPublicModelAliasesForProviderSlugs(slugs) {
  const allowedSlugs = new Set(normalizeProviderSlugs(slugs));
  if (!allowedSlugs.size) return [];
  return [...new Set(getEnabledModelEntries()
    .filter((model) => allowedSlugs.has(model.id))
    .map((model) => model.publicModel)
    .filter(Boolean))];
}

function getInFlight(slug) {
  return inFlightByProvider.get(slug) || 0;
}

function hasCapacity(provider) {
  const max = Number(provider.max_concurrent_requests || 0);
  return max <= 0 || getInFlight(provider.slug) < max;
}

function randomChoice(values) {
  return values[Math.floor(Math.random() * values.length)];
}

function reserveProvider(provider) {
  inFlightByProvider.set(provider.slug, getInFlight(provider.slug) + 1);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const remaining = Math.max(0, getInFlight(provider.slug) - 1);
    if (remaining) inFlightByProvider.set(provider.slug, remaining);
    else inFlightByProvider.delete(provider.slug);
  };
}

function reserveProviderForTest(slug) {
  const provider = getProviderBySlug(slug);
  if (!provider) throw new Error(`Provider ${slug} not found.`);
  if (!hasCapacity(provider)) throw apiError(503, 'provider_capacity_exceeded', 'Provider is at capacity. Wait for active requests to finish before testing.');
  return reserveProvider(provider);
}

function normalizeProviderSlugs(slugs) {
  if (!slugs) return [];
  const values = Array.isArray(slugs) ? slugs : [slugs];
  return [...new Set(values.map((slug) => String(slug || '').trim()).filter(Boolean))];
}

function chooseProviderModel(publicModelAlias, assignedProviderSlugs = null, requiredCapabilities = {}, { affinity, excludedProviderSlugs = [] } = {}) {
  const slugs = normalizeProviderSlugs(assignedProviderSlugs);
  const params = { publicModelAlias };
  const providerFilter = slugs.length
    ? `AND providers.slug IN (${slugs.map((_, index) => `@slug${index}`).join(', ')})
       AND provider_models.public_model = @publicModelAlias`
    : 'AND provider_models.public_model = @publicModelAlias';
  slugs.forEach((slug, index) => {
    params[`slug${index}`] = slug;
  });

  const candidates = getDb().prepare(`
    SELECT
      providers.*,
      provider_models.public_model AS public_model_alias,
      provider_models.upstream_model,
      provider_models.context_limit,
      provider_models.output_limit,
      provider_models.supports_text_input,
      provider_models.supports_image_input,
      provider_models.supports_tools,
      provider_models.supports_reasoning,
      provider_models.reasoning_efforts,
      provider_models.default_reasoning_effort,
      provider_models.reasoning_history_field,
      provider_models.supports_chat_template_kwargs,
      provider_models.supports_parallel_tools
    FROM provider_models
    JOIN providers ON providers.id = provider_models.provider_id
    WHERE providers.enabled = 1
      AND provider_models.enabled = 1
      ${providerFilter}
    ORDER BY providers.priority DESC, providers.name ASC, providers.id ASC
  `).all(params);

  if (!candidates.length) {
    throw apiError(404, 'model_not_found', `Model ${publicModelAlias} is not available.`);
  }

  const capableCandidates = candidates.filter((provider) => {
    if (requiredCapabilities.text && !provider.supports_text_input) return false;
    if (requiredCapabilities.image && !provider.supports_image_input) return false;
    if (requiredCapabilities.tools && !provider.supports_tools) return false;
    if (requiredCapabilities.reasoning && !provider.supports_reasoning) return false;
    if (requiredCapabilities.reasoningEffort) {
      if (!provider.supports_reasoning) return false;
      const supportedEfforts = parseReasoningEfforts(provider.reasoning_efforts);
      if (supportedEfforts !== null && !supportedEfforts.includes(requiredCapabilities.reasoningEffort)) return false;
    }
    if (requiredCapabilities.chatTemplateKwargs && !provider.supports_chat_template_kwargs) return false;
    if (requiredCapabilities.parallelTools && !provider.supports_parallel_tools) return false;
    return true;
  });
  if (!capableCandidates.length) {
    if (requiredCapabilities.reasoningEffort) {
      throw apiError(
        400,
        'reasoning_effort_not_supported',
        `Model ${publicModelAlias} does not support reasoning_effort=${requiredCapabilities.reasoningEffort} in the assigned provider pool.`
      );
    }
    if (requiredCapabilities.chatTemplateKwargs) {
      throw apiError(
        400,
        'chat_template_kwargs_not_supported',
        `Model ${publicModelAlias} does not support chat_template_kwargs in the assigned provider pool.`
      );
    }
    const missing = Object.entries(requiredCapabilities)
      .filter(([capability, required]) => required && !['reasoningEffort', 'chatTemplateKwargs'].includes(capability))
      .map(([capability]) => capability)
      .join(', ');
    throw apiError(400, 'model_capability_unavailable', `Model ${publicModelAlias} has no assigned provider supporting: ${missing}.`);
  }

  const preferredSlug = affinity?.setPool(capableCandidates.map((provider) => provider.slug));
  const excluded = new Set(excludedProviderSlugs);
  const reachableCandidates = capableCandidates.filter((provider) => !excluded.has(provider.slug) && providerAvailability.available(provider.slug));
  if (!reachableCandidates.length) {
    throw apiError(503, 'provider_unavailable', `Providers for ${publicModelAlias} are temporarily unavailable. Retry shortly.`);
  }
  const availableCandidates = reachableCandidates.filter(hasCapacity);
  if (!availableCandidates.length) {
    throw apiError(503, 'provider_capacity_exceeded', `All providers for ${publicModelAlias} are at capacity.`);
  }

  const lowestInFlight = Math.min(...availableCandidates.map((provider) => getInFlight(provider.slug)));
  const leastBusyCandidates = availableCandidates.filter((provider) => getInFlight(provider.slug) === lowestInFlight);
  const preferred = leastBusyCandidates.find((provider) => provider.slug === preferredSlug);
  if (preferred) return preferred;
  const highestPriority = Math.max(...leastBusyCandidates.map((provider) => Number(provider.priority || 0)));
  const topCandidates = leastBusyCandidates.filter((provider) => Number(provider.priority || 0) === highestPriority);
  const candidate = randomChoice(topCandidates);
  return candidate;
}

function inferRequiredCapabilities(payload) {
  const reasoning = validateReasoningControls(payload);
  const contentParts = (payload.messages || []).flatMap((message) => Array.isArray(message?.content) ? message.content : []);
  const hasImages = contentParts.some((part) => part?.type === 'image_url' || part?.type === 'input_image');
  const hasTools = Array.isArray(payload.tools) && payload.tools.length > 0 && payload.tool_choice !== 'none';
  return {
    text: true,
    image: hasImages,
    tools: hasTools,
    parallelTools: Boolean(hasTools && payload.parallel_tool_calls),
    reasoning: reasoning.reasoningRequested,
    reasoningEffort: reasoning.reasoningEffort,
    chatTemplateKwargs: reasoning.hasChatTemplateKwargs
  };
}

async function callChatCompletions(payload, { signal, providerSlug = null, providerSlugs = null, requiredCapabilities = {}, conversation = {}, onAttemptFailure } = {}) {
  const inferred = inferRequiredCapabilities(payload);
  const requirements = {
    text: Boolean(inferred.text || requiredCapabilities.text),
    image: Boolean(inferred.image || requiredCapabilities.image),
    tools: Boolean(inferred.tools || requiredCapabilities.tools),
    parallelTools: Boolean(inferred.parallelTools || requiredCapabilities.parallelTools),
    reasoning: Boolean(inferred.reasoning || requiredCapabilities.reasoning),
    reasoningEffort: requiredCapabilities.reasoningEffort || inferred.reasoningEffort || null,
    chatTemplateKwargs: Boolean(inferred.chatTemplateKwargs || requiredCapabilities.chatTemplateKwargs)
  };
  const affinity = affinityStore.request({ ...conversation, model: payload.model, messages: payload.messages });
  const attemptedSlugs = [];
  let lastError;
  // Two attempts at most, each to a different eligible endpoint. Once a response
  // is returned, its body belongs to the route and is never replayed.
  for (let attempt = 0; attempt < 2; attempt++) {
    signal?.throwIfAborted();
    let provider;
    try {
      provider = chooseProviderModel(payload.model, providerSlugs || providerSlug, requirements, { affinity, excludedProviderSlugs: attemptedSlugs });
    } catch (error) {
      throw lastError || error;
    }
    if (!provider.base_url) {
      if (lastError) throw lastError;
      throw apiError(503, 'provider_misconfigured', `Provider ${provider.slug} has no base URL.`);
    }
    if (!provider.api_key) {
      if (lastError) throw lastError;
      throw apiError(503, 'provider_misconfigured', `Provider ${provider.slug} has no API key placeholder or API key.`);
    }

    if (lastError) onAttemptFailure?.(lastError);
    const release = reserveProvider(provider);
    attemptedSlugs.push(provider.slug);
    try {
      const response = await fetch(chatCompletionsUrl(provider.base_url), {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${provider.api_key}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(buildPayload(payload, provider.upstream_model, provider)),
        signal
      });

      if (!response.ok) {
        const text = await response.text();
        let body;
        try {
          body = JSON.parse(text);
        } catch {
          body = { error: { message: text || response.statusText } };
        }
        const upstreamMessage = body?.error?.message || response.statusText || `${provider.name} request failed.`;
        const code = response.status === 402 || /balance|insufficient/i.test(upstreamMessage)
          ? 'insufficient_provider_balance'
          : 'provider_error';
        // Credential errors can echo parts of the server's provider key, so students get a
        // generic message. Other messages (such as context-length errors) stay visible because
        // clients rely on them, but the raw upstream body is never forwarded.
        const credentialError = response.status === 401 || response.status === 403;
        if (credentialError) console.error(`Provider ${provider.slug} rejected the server credentials: ${upstreamMessage}`);
        const message = credentialError ? 'The upstream provider rejected the server credentials. Contact the course administrator.' : upstreamMessage;
        const error = apiError(credentialError ? 502 : response.status, code, message);
        error.transient = [429, 502, 503, 504].includes(response.status);
        const retryAfter = response.headers.get('retry-after');
        error.retryAfterMs = Math.max(0, Number(retryAfter) * 1000 || Date.parse(retryAfter) - Date.now() || 0);
        error.upstreamUsage = body?.usage;
        throw error;
      }

      return {
        upstream: response,
        provider,
        release,
        complete: (assistantMessage) => {
          providerAvailability.succeeded(provider.slug);
          affinity.complete(provider.slug, assistantMessage);
        },
        fail: () => providerAvailability.failed(provider.slug)
      };
    } catch (error) {
      release();
      error.providerSlug = provider.slug;
      const connectFailure = ['ECONNREFUSED', 'ECONNRESET', 'EPIPE', 'ENOTFOUND', 'EAI_AGAIN', 'UND_ERR_SOCKET', 'UND_ERR_CONNECT_TIMEOUT', 'ETIMEDOUT'].includes(error.cause?.code || error.code);
      const transient = !signal?.aborted && error.name !== 'AbortError' && (error.transient || connectFailure);
      error.upstreamAttempt = true;
      if (transient) providerAvailability.failed(provider.slug, error.retryAfterMs);
      if (!transient || attempt === 1) throw error;
      // Record the rejected attempt separately; it never counts as another
      // logical call. Only explicit upstream usage is charged as consumed tokens.
      lastError = error;
    }
  }
}

async function testProvider({ slug, apiKey, baseUrl, model }) {
  const provider = slug ? getProviderBySlug(slug) : null;
  const targetBaseUrl = String(baseUrl || provider?.base_url || '').replace(/\/+$/, '');
  const targetApiKey = apiKey || provider?.api_key || '';
  const targetModel = model || getDb().prepare(`
    SELECT upstream_model
    FROM provider_models
    WHERE provider_id = ?
    ORDER BY public_model ASC
    LIMIT 1
  `).get(provider?.id)?.upstream_model;

  const warnings = [];
  if (provider && !provider.enabled) warnings.push('Provider is disabled.');
  if (!targetBaseUrl) warnings.push('Base URL is missing.');
  if (!targetApiKey) warnings.push('API key is not configured.');
  if (!targetModel) warnings.push('No provider model mapping is configured.');
  if (warnings.length) {
    return {
      ok: false,
      status: 0,
      body: warnings.join(' '),
      errorMessage: warnings.join(' '),
      diagnostics: { warnings, baseUrl: targetBaseUrl, model: targetModel || null }
    };
  }

  let response;
  try {
    response = await fetch(chatCompletionsUrl(targetBaseUrl), {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${targetApiKey}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: targetModel,
        messages: [{ role: 'user', content: 'Reply with OK.' }],
        max_tokens: 8,
        stream: false
      })
    });
  } catch (error) {
    return {
      ok: false,
      status: 0,
      body: error.message,
      errorMessage: error.message,
      diagnostics: { warnings, baseUrl: targetBaseUrl, model: targetModel }
    };
  }

  const text = await response.text();
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    parsed = null;
  }
  const upstreamMessage = parsed?.error?.message || parsed?.message || null;
  return {
    ok: response.ok,
    status: response.status,
    body: text.slice(0, 1000),
    errorMessage: upstreamMessage,
    diagnostics: { warnings, baseUrl: targetBaseUrl, model: targetModel }
  };
}

async function discoverProviderMetadata({ slug, apiKey, baseUrl, signal }) {
  const provider = slug ? getProviderBySlug(slug) : null;
  const targetBaseUrl = String(baseUrl || provider?.base_url || '').replace(/\/+$/, '');
  const targetApiKey = apiKey || provider?.api_key || '';
  const timeoutMs = Math.min(Math.max(Number(provider?.timeout_ms || config.requestTimeoutMs), 1000), 30000);

  if (!targetBaseUrl) {
    return { ok: false, status: 0, errorMessage: 'Base URL is missing.', models: [], warnings: [] };
  }

  const requestJson = async (url) => {
    const response = await fetch(url, {
      headers: targetApiKey ? { Authorization: `Bearer ${targetApiKey}` } : {},
      redirect: 'error',
      signal: AbortSignal.any([AbortSignal.timeout(timeoutMs), ...(signal ? [signal] : [])])
    });
    const text = await response.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = null;
    }
    return { response, body, text };
  };

  let modelResponse;
  try {
    modelResponse = await requestJson(modelsUrl(targetBaseUrl));
  } catch (error) {
    return {
      ok: false,
      status: 0,
      errorMessage: `Could not query the upstream model catalog: ${error.message}`,
      models: [],
      warnings: []
    };
  }

  if (!modelResponse.response.ok) {
    const upstreamMessage = modelResponse.body?.error?.message || modelResponse.body?.message || modelResponse.body?.detail;
    return {
      ok: false,
      status: modelResponse.response.status,
      errorMessage: upstreamMessage || 'The upstream provider does not expose a compatible model catalog.',
      models: [],
      warnings: []
    };
  }

  if (!Array.isArray(modelResponse.body?.data)) {
    return {
      ok: false,
      status: modelResponse.response.status,
      errorMessage: 'The upstream /models response does not contain a model list.',
      models: [],
      warnings: []
    };
  }

  const models = modelResponse.body.data.map((model) => {
    const settings = officialModelSettings(model);
    return {
      id: String(model?.id || '').trim(),
      ownedBy: String(model?.owned_by || '').trim() || null,
      root: String(model?.root || '').trim() || null,
      maxModelLen: settings.context_limit ?? null,
      settings
    };
  }).filter((model) => model.id);

  if (!models.length) {
    return {
      ok: false,
      status: modelResponse.response.status,
      errorMessage: 'The upstream provider returned no usable models.',
      models: [],
      warnings: []
    };
  }

  const isVllm = models.some((model) => model.ownedBy?.toLowerCase() === 'vllm');
  const warnings = [];
  let version = null;
  if (isVllm) {
    try {
      const versionResponse = await requestJson(`${providerRootUrl(targetBaseUrl)}/version`);
      if (versionResponse.response.ok) {
        version = String(versionResponse.body?.version || '').trim() || null;
      } else if (versionResponse.response.status !== 404) {
        warnings.push(`The optional version endpoint returned HTTP ${versionResponse.response.status}.`);
      }
    } catch (error) {
      warnings.push(`The optional version endpoint could not be queried: ${error.message}`);
    }
  }

  return {
    ok: true,
    status: modelResponse.response.status,
    providerType: isVllm ? 'vllm' : 'openai-compatible',
    version,
    models,
    warnings
  };
}

module.exports = {
  buildPayload,
  callChatCompletions,
  chatCompletionsUrl,
  chooseProviderModel,
  discoverProviderMetadata,
  getEnabledModelEntries,
